app2c/advanced.html:
{% extends "base_2c.html" %}
{% block page_title %}账户 · 小歪{% endblock %}
{% block extra_head %}<script src="{{ url_for('static', filename='vendor/vue.global.prod.min.js') }}"></script>{% endblock %}
{% block content %}
<div id="advancedApp">
  <div class="pagehd">
    <div>
      <div class="eyebrow">ACCOUNT</div>
      <h1>账户</h1>
      <p>账号资料与密码都在这里管理。</p>
    </div>
  </div>

  <div class="adv-panel">
    <div class="panel-head">
      <div><b>账号资料</b><small>[[ user.email ]]</small></div>
    </div>
    <div>
      <form class="inline-form" @submit.prevent="saveProfile">
        <input class="tinput" v-model="profileName" placeholder="显示名称">
        <button :disabled="!!busyAction" type="submit" class="btn primary">保存名称</button>
      </form>
      <form class="password-form" @submit.prevent="changePassword">
        <input class="tinput" v-model="password.old_password" type="password" placeholder="旧密码">
        <input class="tinput" v-model="password.new_password" type="password" placeholder="新密码">
        <input class="tinput" v-model="password.confirm_password" type="password" placeholder="确认新密码">
        <button :disabled="!!busyAction" type="submit" class="btn primary">更新密码</button>
      </form>
      <form method="post" action="{{ url_for('auth.logout') }}">
        <button :disabled="!!busyAction" type="submit" class="btn ghost">退出登录</button>
      </form>
    </div>
  </div>

  <p v-if="busyAction" role="status">正在处理，请稍候…</p>
  <p class="lead" v-if="msg">[[ msg ]]</p>
</div>
{% endblock %}
{% block scripts %}
<script>
const { createApp } = Vue;
createApp({
  delimiters:['[[',']]'],
  data(){ return {
    msg:'', loading:false,
    user:{email:'',display_name:''}, profileName:'',
    password:{old_password:'',new_password:'',confirm_password:''},
  }; },
  methods:{
    async api(url, opts){
      const r=await fetch(url, opts||{});
      const d=await r.json().catch(()=>({ok:false,error:'响应解析失败'}));
      if(!r.ok || d.ok===false) throw new Error(d.error||('HTTP '+r.status));
      return d;
    },
    applyPayload(d){
      this.user=d.user||this.user;
      this.profileName=this.user.display_name||'';
    },
    async load(){
      this.loading=true; this.msg='';
      try{ this.applyPayload(await this.api('/api/advanced')); }
      catch(e){ this.msg=e.message||'加载失败'; }
      finally{ this.loading=false; }
    },
    async saveProfile(){
      try{
        const d=await this.api('/api/advanced/profile',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({display_name:this.profileName})});
        this.user=d.user; this.profileName=d.user.display_name||''; this.msg='名称已保存';
      }catch(e){ this.msg=e.message||'保存失败'; }
    },
    async changePassword(){
      try{
        await this.api('/api/advanced/password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(this.password)});
        this.password={old_password:'',new_password:'',confirm_password:''}; this.msg='密码已更新';
      }catch(e){ this.msg=e.message||'更新失败'; }
    },
  },
  mounted(){ this.load(); },
}).mount('#advancedApp');
</script>
{% endblock %}

app2c/devices.html:
{% extends "base_2c.html" %}
{% block page_title %}我的设备 · 小歪{% endblock %}
{% block global_setup_suppress_device %}1{% endblock %}
{% block extra_head %}<script src="{{ url_for('static', filename='vendor/vue.global.prod.min.js') }}"></script>{% endblock %}
{% block content %}
<div id="app">
  <div class="pagehd"><div><div class="eyebrow">DEVICES · [[ devices.length ]] BOUND</div><h1>我的设备</h1><p>绑定与切换你的 Brufik 机器人。</p></div></div>
  <div class="dev" v-for="d in devices" :key="d.device_id">
    <div class="di"><svg viewBox="0 0 24 24"><rect x="6" y="3" width="12" height="18" rx="2"/><path d="M11 18h2"/></svg></div>
    <div style="flex:1"><b>[[ d.display_name ]]</b><small><span class="led" :class="{off: d.device_id!==current}"></span>[[ d.device_id===current?'当前':'已绑定' ]] · [[ d.device_id ]]</small></div>
    <div class="btngroup">
      <button :disabled="!!busyAction" class="btn" :class="d.device_id===current?'primary':'ghost'" @click="select(d)">[[ d.device_id===current?'当前':'切换' ]]</button>
      <button :disabled="!!busyAction" class="btn ghost" @click="unbind(d)">解绑</button>
    </div>
  </div>
  <div style="display:flex;gap:8px;margin-top:16px;max-width:560px;flex-wrap:wrap">
    <input class="tinput" v-model="newId" placeholder="设备 ID，例如 brfk_aabbccddeeff1234" @keyup.enter="bind">
    <button :disabled="!!busyAction" class="btn primary" @click="bind">＋ 绑定新设备</button>
  </div>
  <p class="device-id-hint">设备开机联网后，屏幕上会显示它的 <code>device_id</code>；设备须在线才能绑定。</p>
  <p v-if="busyAction" role="status">正在处理，请稍候…</p>
  <p class="lead" v-if="msg">[[ msg ]]</p>
</div>
{% endblock %}
{% block scripts %}
<script>
const { createApp } = Vue;
createApp({ delimiters:['[[',']]'], data(){return{devices:[],current:'',newId:'',msg:'',msgOk:true};},
  methods:{
    async load(){ const r=await (await fetch('/app/api/devices')).json(); if(r.ok){ this.devices=r.devices||[]; this.current=r.current_device_id||''; } else { this.msgOk=false; this.msg=r.error||'加载失败'; } },
    async select(d){ await DeskbotUI.switchDevice(d.device_id); },
    async bind(){
      const id=this.newId.trim();
      if(!id){ this.msgOk=false; this.msg='绑定失败：请输入 device_id'; return; }
      const r=await (await fetch('/app/api/devices',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({device_id:id})})).json();
      if(r.ok){ this.newId=''; this.msgOk=true; this.msg=r.message||'绑定成功'; await DeskbotUI.switchDevice(r.current_device_id||id); }
      else { this.msgOk=false; this.msg=r.error||'绑定失败'; }
    },
    async unbind(d){ if(!confirm('确定解绑这台设备？')) return; const r=await (await fetch('/app/api/devices/'+encodeURIComponent(d.device_id),{method:'DELETE'})).json(); if(r.ok){ this.msgOk=true; this.msg='已解绑 '+d.device_id; if(d.device_id===DeskbotUI.device)await DeskbotUI.reloadDevice('');else this.load(); } else { this.msgOk=false; this.msg=r.error||'解绑失败'; } } },
  mounted(){ this.load(); } }).mount('#app');
</script>
{% endblock %}

app2c/flash_rom.html:
{% extends "base_2c.html" %}
{% block page_title %}固件烧录 · 小歪{% endblock %}
{% block extra_head %}
<script src="{{ url_for('static', filename='vendor/vue.global.prod.min.js') }}"></script>
<style>
.flash-grid{display:grid;grid-template-columns:minmax(280px,360px) 1fr;gap:16px;align-items:start}
@media(max-width:960px){.flash-grid{grid-template-columns:1fr}}
.flash-card{background:#12141a;border:1px solid #2a2d36;border-radius:12px;padding:14px 16px}
.flash-card h3{margin:0 0 10px;font-size:14px;letter-spacing:.06em;color:#9a9a90}
.flash-row{display:flex;gap:8px;align-items:center;margin-bottom:10px;flex-wrap:wrap}
.flash-row label{font-size:12px;color:#9a9a90;min-width:52px}
.flash-select,.flash-input{flex:1;min-width:180px;background:#0d0f14;border:1px solid #333641;color:#f6f5ef;border-radius:8px;padding:8px 10px;font-family:inherit}
.flash-log{background:#0a0b0f;border:1px solid #252830;border-radius:10px;padding:10px;height:360px;overflow:auto;font:12px/1.45 "Space Mono",monospace;color:#d8d6ce;white-space:pre-wrap;word-break:break-word}
.flash-roms{display:flex;flex-direction:column;gap:8px;max-height:280px;overflow:auto}
.flash-rom{border:1px solid #2a2d36;border-radius:10px;padding:10px 12px;cursor:pointer;background:#0d0f14}
.flash-rom.on{border-color:#ff5a00;background:#17120e}
.flash-rom b{display:block;font-size:13px}
.flash-rom small{color:#9a9a90}
.flash-meta{font-size:12px;color:#9a9a90;margin-top:8px}
.flash-err{color:#ff6b6b;font-size:13px;margin-top:8px}
.flash-hint{font-size:12px;color:#9a9a90;margin:0 0 12px;line-height:1.5}
.flash-badge{display:inline-block;padding:2px 8px;border-radius:999px;background:#1f232d;color:#c8c6be;font-size:11px;margin-left:6px}
</style>
{% endblock %}
{% block content %}
<div id="flashApp">
  <div class="pagehd">
    <div>
      <div class="eyebrow">FIRMWARE · LOCAL FLASH</div>
      <h1>固件烧录</h1>
      <p>在运行本服务的电脑上，通过 USB 串口烧录小歪 ROM，并查看/发送串口指令。</p>
    </div>
    <div class="btngroup">
      <button type="button" class="btn ghost" @click="refreshAll" :disabled="busy">刷新</button>
    </div>
  </div>

  <p class="flash-hint">
    本页依赖本机串口与 PlatformIO（<code>pio</code>）。请将设备 USB 接到<strong>运行 deskbot-server 的电脑</strong>，再选择串口与 ROM。
    预编译包可放到 <code>hardware/releases/*.bin</code>。
  </p>

  <div class="flash-grid">
    <div class="flash-side">
      <div class="flash-card">
        <h3>串口</h3>
        <div class="flash-row">
          <label>设备</label>
          <select class="flash-select" v-model="port">
            <option value="">请选择串口</option>
            <option v-for="p in ports" :key="p.port" :value="p.port">[[ p.port ]]</option>
          </select>
          <button type="button" class="btn ghost" @click="loadPorts">扫描</button>
        </div>
        <p class="flash-meta">检测到 [[ ports.length ]] 个串口 · 监视 [[ monitorOn ? '已连接' : '未连接' ]]</p>
      </div>

      <div class="flash-card" style="margin-top:12px">
        <h3>ROM 列表</h3>
        <div class="flash-roms">
          <div v-for="r in roms" :key="r.id" class="flash-rom" :class="{on: selectedRomId===r.id}" @click="selectedRomId=r.id">
            <b>[[ r.label ]]<span class="flash-badge">[[ r.kind ]]</span></b>
            <small>[[ romMeta(r) ]]</small>
            <div v-if="r.downloadable" style="margin-top:6px">
              <a class="btn ghost" style="padding:4px 8px;font-size:12px" :href="'/api/flash/roms/'+encodeURIComponent(r.id)+'/download'">下载</a>
            </div>
          </div>
        </div>
      </div>

      <div class="flash-card" style="margin-top:12px">
        <h3>操作</h3>
        <div class="flash-row">
          <button type="button" class="btn ghost" @click="doBuild" :disabled="busy">仅编译</button>
          <button type="button" class="btn primary" @click="doUpload" :disabled="busy || !port">烧录</button>
          <button type="button" class="btn ghost" @click="doCancel" :disabled="!jobRunning">取消</button>
        </div>
        <div class="flash-row">
          <button type="button" class="btn ghost" @click="startMonitor" :disabled="!port">打开串口日志</button>
          <button type="button" class="btn ghost" @click="stopMonitor" :disabled="!monitorOn">关闭串口</button>
        </div>
        <p class="flash-meta" v-if="status.job">任务 [[ status.job.action ]] · [[ status.job.status ]]</p>
      </div>
    </div>

    <div class="flash-main">
      <div class="flash-card">
        <h3>输出日志</h3>
        <div class="flash-log" ref="logBox">[[ logText ]]</div>
        <div class="flash-row" style="margin-top:10px">
          <input class="flash-input" v-model="cmdText" placeholder="发送串口指令，例如 help 或 pb status" @keyup.enter="sendCmd">
          <button type="button" class="btn primary" @click="sendCmd" :disabled="!monitorOn && !status.serial_port">发送</button>
        </div>
        <p class="flash-err" v-if="err">[[ err ]]</p>
      </div>
    </div>
  </div>
</div>
{% endblock %}
{% block scripts %}
<script>
const { createApp } = Vue;
createApp({
  delimiters: ['[[', ']]'],
  data(){
    return {
      ports: [],
      roms: [],
      selectedRomId: 'source',
      port: '',
      status: { running: false, job: null, serial_port: null },
      logLines: [],
      logSince: 0,
      cmdText: '',
      err: '',
      monitorOn: false,
      ws: null,
      pollTimer: null,
    };
  },
  computed:{
    logText(){ return this.logLines.join('\n'); },
    busy(){ return !!this.status.running; },
    jobRunning(){ return !!this.status.running; },
  },
  methods:{
    async api(url, opts){
      const r = await fetch(url, Object.assign({ cache: 'no-store' }, opts || {}));
      const data = await r.json().catch(() => ({}));
      if(!r.ok || data.ok === false){
        throw new Error(data.error || ('HTTP '+r.status));
      }
      return data;
    },
    romMeta(r){
      const parts = [];
      if(r.size != null) parts.push(Math.round(r.size/1024)+' KB');
      if(r.mtime) parts.push(new Date(r.mtime*1000).toLocaleString());
      if(r.flash_mode === 'download_only') parts.push('仅下载');
      return parts.join(' · ') || r.id;
    },
    appendLog(lines){
      if(!lines || !lines.length) return;
      this.logLines.push(...lines);
      if(this.logLines.length > 5000) this.logLines.splice(0, this.logLines.length - 5000);
      this.$nextTick(() => {
        const el = this.$refs.logBox;
        if(el) el.scrollTop = el.scrollHeight;
      });
    },
    async loadPorts(){
      const d = await this.api('/api/flash/ports');
      this.ports = d.ports || [];
      if(!this.port && this.ports.length) this.port = this.ports[0].port;
    },
    async loadRoms(){
      const d = await this.api('/api/flash/roms');
      this.roms = d.roms || [];
      if(!this.roms.find(x => x.id === this.selectedRomId)){
        this.selectedRomId = (this.roms[0] && this.roms[0].id) || 'source';
      }
    },
    async pollStatus(){
      try{
        const d = await this.api('/api/flash/status?since='+this.logSince);
        this.status = d;
        const chunk = (d.log && d.log.lines) || [];
        if(chunk.length){
          this.appendLog(chunk);
          this.logSince = d.log.since + chunk.length;
        }
      }catch(e){
        this.err = String(e.message || e);
      }
    },
    async refreshAll(){
      this.err = '';
      await Promise.all([this.loadPorts(), this.loadRoms(), this.pollStatus()]);
    },
    async doBuild(){
      this.err = '';
      try{
        await this.api('/api/flash/build', { method:'POST' });
        await this.pollStatus();
      }catch(e){ this.err = String(e.message || e); }
    },
    async doUpload(){
      this.err = '';
      if(!this.port){ this.err = '请选择串口'; return; }
      try{
        await this.api('/api/flash/upload', {
          method:'POST',
          headers:{'Content-Type':'application/json'},
          body: JSON.stringify({ port: this.port, rom_id: this.selectedRomId }),
        });
        await this.pollStatus();
      }catch(e){ this.err = String(e.message || e); }
    },
    async doCancel(){
      this.err = '';
      try{
        await this.api('/api/flash/cancel', { method:'POST' });
        await this.pollStatus();
      }catch(e){ this.err = String(e.message || e); }
    },
    closeWs(){
      if(this.ws){
        try{ this.ws.close(); }catch(_e){}
      }
      this.ws = null;
      this.monitorOn = false;
    },
    async startMonitor(){
      this.err = '';
      if(!this.port){ this.err = '请选择串口'; return; }
      this.closeWs();
      try{
        const proto = location.protocol === 'https:' ? 'wss:' : 'ws:';
        const url = proto + '//' + location.host + '/api/flash/serial/ws?port=' + encodeURIComponent(this.port);
        const ws = new WebSocket(url);
        ws.binaryType = 'arraybuffer';
        ws.onopen = () => { this.monitorOn = true; this.appendLog(['==> 串口监视已连接 '+this.port]); };
        ws.onclose = () => { this.monitorOn = false; this.appendLog(['==> 串口监视已断开']); };
        ws.onerror = () => { this.err = '串口 WebSocket 连接失败'; };
        ws.onmessage = (ev) => {
          if(typeof ev.data === 'string'){
            this.appendLog([ev.data]);
          }else if(ev.data instanceof ArrayBuffer){
            const dec = new TextDecoder('utf-8', { fatal:false });
            this.appendLog([dec.decode(ev.data)]);
          }
        };
        this.ws = ws;
      }catch(e){ this.err = String(e.message || e); }
    },
    async stopMonitor(){
      this.closeWs();
      try{
        await this.api('/api/flash/monitor/stop', { method:'POST' });
      }catch(e){ this.err = String(e.message || e); }
    },
    async sendCmd(){
      const text = (this.cmdText || '').trim();
      if(!text) return;
      this.err = '';
      try{
        if(this.ws && this.ws.readyState === WebSocket.OPEN){
          this.ws.send(text);
        }else{
          await this.api('/api/flash/monitor/send', {
            method:'POST',
            headers:{'Content-Type':'application/json'},
            body: JSON.stringify({ text }),
          });
        }
        this.appendLog(['>> '+text]);
        this.cmdText = '';
      }catch(e){ this.err = String(e.message || e); }
    },
  },
  mounted(){
    this.refreshAll();
    this.pollTimer = setInterval(() => this.pollStatus(), 1200);
  },
  beforeUnmount(){
    if(this.pollTimer) clearInterval(this.pollTimer);
    this.closeWs();
  },
}).mount('#flashApp');
</script>
{% endblock %}

app2c/home.html:
{% extends "base_2c.html" %}
{% block page_title %}家 · 小歪{% endblock %}
{% block extra_head %}
<script>
  window.__HOME_FACE__ = {
    w: {{ face_lcd_w|int }},
    h: {{ face_lcd_h|int }},
    defaultAnim: {{ expr_default_anim|tojson }},
  };
</script>
<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js"
  }
}
</script>
<script src="{{ url_for('static', filename='vendor/vue.global.prod.min.js') }}"></script>
<script src="{{ url_for('static', filename='face_preview_2c.js') }}"></script>
{% endblock %}
{% block content %}
<div id="home">
  <div class="pagehd">
    <div>
      <div class="eyebrow">SYSTEM · ONLINE</div>
      <h1>[[ greeting ]]，[[ owner ]]</h1>
      <p>专属于你的桌面机器人小歪现在很有精神。</p>
    </div>
    <a v-if="!bound" class="btn ghost" href="{{ url_for('app2c.devices') }}">＋ 绑定设备</a>
  </div>

  <!-- 设备主控台：表情 / 3D / 摄像头 三块等大 -->
  <div class="stage home-console">
    <div class="brackets"><span class="tl"></span><span class="tr"></span><span class="bl"></span><span class="br"></span></div>
    <div class="stage-hd">
      <span class="unit">UNIT · [[ deviceName ]]</span>
      <span class="uid">[[ deviceId || '未绑定' ]]</span>
    </div>

    <div class="home-media">
      <!-- 表情 -->
      <div class="media-tile" aria-label="当前表情">
        <div class="media-hd"><span>表情 · 当前</span><b>[[ faceLabel ]]</b></div>
        <div class="media-stage">
          <div class="face"><div class="scanline"></div><svg viewBox="0 0 284 240" v-html="homeFaceSvg" aria-hidden="true"></svg></div>
        </div>
      </div>
      <!-- 3D 模型 -->
      <div class="media-tile" aria-label="3D 小歪状态模拟">
        <div class="media-hd"><span>3D · SIM</span><b>小歪</b></div>
        <div class="media-stage">
          <div class="home-robot-host" ref="homeRobot3dHost">
            <p v-if="homeRobotError" class="home-robot-fallback">[[ homeRobotError ]]</p>
          </div>
        </div>
      </div>
      <!-- 摄像头（老电视：旋钮开机） -->
      <div class="media-tile" aria-label="摄像头画面">
        <div class="media-hd"><span>CAMERA · TV</span><b>[[ cameraStateLabel ]]</b></div>
        <div class="media-stage home-tv">
          <img v-if="tvPower && camera.imageUrl" :src="camera.imageUrl" alt="摄像头实时画面">
          <div v-else-if="tvPower" class="home-camera-empty">
            <b>[[ camera.statusText ]]</b>
            <small>[[ bound ? '等待设备上行 camera_view 画面' : '绑定并选择设备后显示实时画面' ]]</small>
          </div>
          <div v-else class="home-tv-standby">
            <span>NO SIGNAL</span>
            <small>拧动旋钮查看实时画面</small>
          </div>
          <button type="button" class="tv-power" :class="{on:tvPower}" @click="toggleTvPower"
            :aria-pressed="tvPower" :title="tvPower ? '关闭摄像头' : '打开摄像头'">
            <svg viewBox="0 0 48 48" aria-hidden="true">
              <circle class="p-ring" cx="24" cy="28" r="12"/>
              <line class="p-bar" x1="24" y1="7" x2="24" y2="23"/>
            </svg>
          </button>
        </div>
      </div>
    </div>

  </div>

  <!-- 快捷入口：一行 5 块 -->
  <section class="home-quicknav" aria-label="快捷入口">
    <a class="quicknav-tile" href="{{ url_for('flash.flash_page') }}">
      <span class="qn-ico">{{ icon('flash') }}</span>
      <b>烧录固件</b><small>USB 串口 · 下载 ROM</small>
    </a>
    <a class="quicknav-tile" href="{{ url_for('app2c.memories') }}">
      <span class="qn-ico">{{ icon('memory') }}</span>
      <b>记忆</b><small>记住重要的事</small>
    </a>
    <a class="quicknav-tile" href="{{ url_for('app2c.people') }}">
      <span class="qn-ico">{{ icon('people') }}</span>
