  <!-- 快捷下发：实验台简版（仅预置动作 / 预置表情 / 指定文字 TTS） -->
  <section class="home-quick" aria-label="快捷下发">
    <div class="home-quick-panel">
      <div class="home-quick-hd"><b>舵机控制</b><small>仅下发预置动作</small></div>
