{% block scripts %}
<script>
const { createApp } = Vue;
const HOME_FACE = window.__HOME_FACE__ || {};
const HOME_FACE_LCD_W = Number(HOME_FACE.w) || 284;
const HOME_FACE_LCD_H = Number(HOME_FACE.h) || 240;
const HOME_EXPR_DEFAULT_ANIM = HOME_FACE.defaultAnim || {
  elements: {
    nose: [{shape:'circle',x:142,y:124,r:11}],
    eye_l: [{shape:'circle',x:93,y:107,r:16}],
    eye_r: [{shape:'circle',x:191,y:107,r:16}],
    mouth: [{shape:'rect',x:102,y:151,w:80,h:20}],
    extra: [],
  },
};
const HOME_ROBOT_CENTER = 90;
/** WS 基址与当前页面 host 对齐（避免用 127.0.0.1 打开页面却连局域网 IP）。 */
function alignWsBaseToPageHost(base) {
  const raw = String(base || '').trim();
  if (!raw) return raw;
  try {
    const u = new URL(raw);
    if (window.location.hostname) u.hostname = window.location.hostname;
    return u.toString().replace(/\/$/, '');
  } catch (_) { return raw; }
}
createApp({
  delimiters: ['[[', ']]'],
  data(){ return {
    greeting:'你好', owner:{{ (nav_display_name or '主人')|tojson }},
    bound:false, deviceName:'未绑定', deviceId:'',
    tvPower:false, // 老电视旋钮（sessionStorage 记忆）
    scenes:[], emotionMap:{},
    // 设备表情模拟：simScene=已下发表情行(循环动画)，null=走 idle 映射；talkEndsAt=说话口型结束时刻
    // talkRows=服务端按音素口型表估算的表情行(与设备 pb 同款)，按行时间轴播放
    simScene:null, simSince:0, simNow:0, talkEndsAt:null,
    talkRows:[], talkCums:[], talkT0:0,
    quick:{servo:{presets:[],busy:false},pb:{scenes:[],selected:'',busy:false},tts:{text:'你好，我是小歪。',busy:false},msg:''},
    homeRobotError:'', homeRobotServo:{x:90,y:90},
    cameraViewWsBase: alignWsBaseToPageHost({{ camera_view_ws_base|tojson }}),
    camera:{ws:null,status:'idle',statusText:'选择设备后显示摄像头画面',imageUrl:'',frameBytes:0},
  }; },
  computed:{
    homeFaceSvg(){
      const preview = window.DeskbotFacePreview;
      if(!preview) return '';
      const els = this.faceElsNow();
      if(!els) return '';
      // 表情卡与 3D 贴图共用同一份 svg：已下发表情走动画循环，说话中叠口型
      return preview.sceneToSvg({name:'sim', frames:[{ms:1000, elements:els}]}, 0);
    },
    faceLabel(){
      const s = this.simBaseScene();
      if(!s) return '待机';
      return s.title || s.name || '待机';
    },
    cameraStateLabel(){
      if(!this.tvPower) return '待机';
      const st = this.camera.status;
      if(this.camera.imageUrl) return '实时画面';
      if(st === 'connecting' || st === 'connected') return '搜索信号';
      if(st === 'error' || st === 'closed') return '信号中断';
      return '无信号';
    },
    homeRobotYawDeg(){
      const x = Number(this.homeRobotServo && this.homeRobotServo.x);
      return Number.isFinite(x) ? x - HOME_ROBOT_CENTER : 0;
    },
    homeRobotPitchDeg(){
      const y = Number(this.homeRobotServo && this.homeRobotServo.y);
      return Number.isFinite(y) ? y - HOME_ROBOT_CENTER : 0;
    },
  },
  methods:{
    async j(u){ try{ return await (await fetch(u)).json(); }catch(e){ return {}; } },
    async api(u){ const r=await fetch(u,{cache:'no-store'}); return await r.json(); },
    closeHomeCamera(){
      if(this.camera.ws){ try{ this.camera.ws.close(); }catch(_e){} }
      this.camera.ws = null;
    },
    toggleTvPower(){
      this.tvPower = !this.tvPower;
      try{ sessionStorage.setItem('home_tv_power', this.tvPower ? '1' : '0'); }catch(_e){}
      if(this.tvPower){
        this.openHomeCamera();
      }else{
        this.closeHomeCamera();
        if(this.camera.imageUrl){ URL.revokeObjectURL(this.camera.imageUrl); this.camera.imageUrl = ''; }
        this.camera.status = 'idle';
      }
    },
    async openHomeCamera(){
      if(!this.bound || !this.deviceId || !this.cameraViewWsBase){
        this.closeHomeCamera();
        this.camera.status='idle';
        this.camera.statusText='选择设备后显示摄像头画面';
        return;
      }
      this.closeHomeCamera();
      try{
        const url = new URL(this.cameraViewWsBase);
        url.searchParams.set('device_id', this.deviceId);
        this.camera.status='connecting';
        this.camera.statusText='正在连接摄像头';
        const ws = new WebSocket(url.toString());
        ws.binaryType = 'blob';
        ws.onopen = () => { this.camera.status='connected'; this.camera.statusText='等待摄像头画面'; };
        ws.onclose = () => { this.camera.status='closed'; this.camera.statusText='摄像头连接已断开'; };
        ws.onerror = () => { this.camera.status='error'; this.camera.statusText='摄像头连接失败'; };
        ws.onmessage = (ev) => {
          if(ev.data instanceof Blob){
            if(this.camera.imageUrl) URL.revokeObjectURL(this.camera.imageUrl);
            this.camera.frameBytes = ev.data.size;
            this.camera.imageUrl = URL.createObjectURL(ev.data);
            this.camera.status='streaming';
            this.camera.statusText='实时画面';
          }
        };
        this.camera.ws = ws;
      }catch(_e){
        this.camera.status='error';
        this.camera.statusText='摄像头连接失败';
      }
    },
    setGreeting(){
      const h=new Date().getHours();
      this.greeting = h<6?'凌晨好' : h<9?'早上好' : h<12?'上午好' : h<14?'中午好' : h<18?'下午好' : '晚上好';
    },
    drawHomeRobotFace(canvas){
      if(!canvas) return;
      const ctx = canvas.getContext('2d');
      if(!ctx) return;
      ctx.fillStyle = '#0d0f14';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      const elements = (HOME_EXPR_DEFAULT_ANIM && HOME_EXPR_DEFAULT_ANIM.elements) || {};
      const colors = {eye_l:'#f6f5ef', eye_r:'#f6f5ef', nose:'#ffb928', mouth:'#ff5a00', extra:'#f6f5ef'};
      for(const key of ['eye_l','eye_r','nose','mouth','extra']){
        for(const shape of (elements[key] || [])) this.drawHomeRobotShape(ctx, shape, colors[key] || '#f6f5ef');
      }
    },
    drawHomeRobotShape(ctx, shape, color){
      if(!shape) return;
      const kind = String(shape.shape || 'rect').toLowerCase();
      ctx.fillStyle = shape.color || color;
      ctx.strokeStyle = shape.color || color;
      ctx.lineWidth = Math.max(1, Number(shape.line_width) || 2);
      if(kind === 'circle'){
        ctx.beginPath();
        ctx.arc(Number(shape.x) || 0, Number(shape.y) || 0, Math.max(1, Number(shape.r) || 4), 0, Math.PI * 2);
        ctx.fill();
        return;
      }
      if(kind === 'line'){
        ctx.beginPath();
        ctx.moveTo(Number(shape.x1 ?? shape.x) || 0, Number(shape.y1 ?? shape.y) || 0);
        ctx.lineTo(Number(shape.x2 ?? shape.x) || 0, Number(shape.y2 ?? shape.y) || 0);
        ctx.stroke();
        return;
      }
      const x = Number(shape.x) || 0, y = Number(shape.y) || 0;
      const w = Math.max(1, Number(shape.w) || 12), h = Math.max(1, Number(shape.h) || 6);
      if(kind === 'rect_outline') ctx.strokeRect(x, y, w, h);
      else ctx.fillRect(x, y, w, h);
    },
    updateHomeRobotFace(){
      // 3D 模型屏幕上的表情与「表情 · 当前」卡片保持一致：直接把同一份 homeFaceSvg 光栅化到贴图
      const state = this._homeRobot3d;
      if(!state || !state.faceCanvas || !state.faceTexture) return;
      const inner = this.homeFaceSvg;
      if(!inner){ return; } // 预览组件还没就绪时保留初始绘制
      const cv = state.faceCanvas;
      // viewBox 与「表情 · 当前」卡片一致（284×240 设计坐标系），确保两处表情完全相同
      const svg = '<svg xmlns="http://www.w3.org/2000/svg" width="' + cv.width + '" height="' + cv.height + '" viewBox="0 0 284 240" preserveAspectRatio="xMidYMid meet">'
        + '<rect width="284" height="240" fill="#0d0f14"/>' + inner + '</svg>';
      const img = new Image();
      img.onload = () => {
        const st = this._homeRobot3d;
        if(!st || st.faceCanvas !== cv) return; // 已销毁或被替换
        const ctx = cv.getContext('2d');
        if(!ctx) return;
        ctx.clearRect(0, 0, cv.width, cv.height);
        ctx.drawImage(img, 0, 0, cv.width, cv.height);
        st.faceTexture.needsUpdate = true;
      };
      img.onerror = () => {};
      img.src = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg);
    },
    async ensureHomeThree(){
      if(window.__HOME_THREE__) return window.__HOME_THREE__;
      if(!this._homeThreePromise){
        this._homeThreePromise = import('three').then((mod) => {
          window.__HOME_THREE__ = mod;
          return mod;
        }).catch((e) => {
          this._homeThreePromise = null;
          throw e;
        });
      }
      return this._homeThreePromise;
    },
    makeHomeForwardArrow(THREE){
      const mat = new THREE.MeshStandardMaterial({color:0x30d158,metalness:0.05,roughness:0.45});
      const group = new THREE.Group();
      const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.025,0.025,0.55,10), mat);
      shaft.rotation.x = Math.PI / 2;
      shaft.position.set(0,0.015,0.28);
      group.add(shaft);
      const tip = new THREE.Mesh(new THREE.ConeGeometry(0.09,0.2,10), mat);
      tip.rotation.x = Math.PI / 2;
      tip.position.set(0,0.015,0.62);
      group.add(tip);
      group.position.set(0,0.005,1.05);
      return group;
    },
    syncHomeRobotServo(){
      const state = this._homeRobot3d;
      const THREE = window.__HOME_THREE__;
      if(!state || !state.headPivot || !THREE) return;
      state.targetHeadYaw = THREE.MathUtils.degToRad(this.homeRobotYawDeg);
      state.targetHeadPitch = THREE.MathUtils.degToRad(this.homeRobotPitchDeg);
    },
    disposeHomeRobot3d(){
      if(this._homeRobotAnimId){ cancelAnimationFrame(this._homeRobotAnimId); this._homeRobotAnimId = null; }
      if(this._homeRobotResizeObs){ try{ this._homeRobotResizeObs.disconnect(); }catch(_e){} this._homeRobotResizeObs = null; }
      const state = this._homeRobot3d;
      if(state && state.renderer){
        if(state.faceTexture){ try{ state.faceTexture.dispose(); }catch(_e){} }
        try{ state.renderer.dispose(); }catch(_e){}
        if(state.renderer.domElement && state.renderer.domElement.parentNode){
          state.renderer.domElement.parentNode.removeChild(state.renderer.domElement);
        }
      }
      this._homeRobot3d = null;
    },
    async homeRobotInit3d(){
      this.disposeHomeRobot3d();
      this.homeRobotError = '';
      const host = this.$refs.homeRobot3dHost;
      if(!host) return;
      let THREE;
      try{ THREE = await this.ensureHomeThree(); }
      catch(_e){ this.homeRobotError = 'Three.js 加载失败'; return; }
      if(!host.isConnected) return;
      let renderer;
      try{ renderer = new THREE.WebGLRenderer({antialias:true,alpha:false,preserveDrawingBuffer:true}); }
      catch(_e){ this.homeRobotError = 'WebGL 不可用'; return; }

      const w = Math.max(180, host.clientWidth || 420);
      const h = Math.max(180, host.clientHeight || 300);
      const scene = new THREE.Scene();
      scene.background = new THREE.Color(0x111318);
      const camera = new THREE.PerspectiveCamera(38, w / h, 0.08, 50);
      camera.position.set(0,0.92,2.65);
      camera.lookAt(0,0.78,0);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
      renderer.setSize(w, h, false);
      host.appendChild(renderer.domElement);

      scene.add(new THREE.AmbientLight(0xffffff,0.7));
      const key = new THREE.DirectionalLight(0xffffff,0.95);
      key.position.set(1.5,3.5,2.5);
      scene.add(key);
      const rim = new THREE.DirectionalLight(0xff7a1a,0.35);
      rim.position.set(-2,1.2,-1.5);
      scene.add(rim);
      scene.add(new THREE.GridHelper(2.4,8,0x55565d,0x25272f));
      scene.add(this.makeHomeForwardArrow(THREE));

      const turntable = new THREE.Group();
      scene.add(turntable);
      const bodyMat = new THREE.MeshStandardMaterial({color:0x4f535a,roughness:0.58,metalness:0.18});
      const headMat = new THREE.MeshStandardMaterial({color:0xf6f5ef,roughness:0.42,metalness:0.06});
      const neckMat = new THREE.MeshStandardMaterial({color:0xff5a00,roughness:0.36,metalness:0.18});
      const base = new THREE.Mesh(new THREE.CylinderGeometry(0.55,0.62,0.07,24), new THREE.MeshStandardMaterial({color:0x25272f,roughness:0.58}));
      base.position.y = -0.02;
      turntable.add(base);
      const body = new THREE.Mesh(new THREE.BoxGeometry(0.82,0.62,0.52), bodyMat);
      body.position.y = 0.28;
      turntable.add(body);
      const neck = new THREE.Mesh(new THREE.CylinderGeometry(0.09,0.12,0.22,16), neckMat);
      neck.position.y = 0.66;
      turntable.add(neck);
      const headPivot = new THREE.Group();
      headPivot.position.y = 0.8;
      turntable.add(headPivot);
      const head = new THREE.Mesh(new THREE.BoxGeometry(0.62,0.5,0.54), headMat);
      head.position.y = 0.22;
      headPivot.add(head);

      const faceCanvas = document.createElement('canvas');
      faceCanvas.width = HOME_FACE_LCD_W;
      faceCanvas.height = HOME_FACE_LCD_H;
      this.drawHomeRobotFace(faceCanvas);
      const faceTexture = new THREE.CanvasTexture(faceCanvas);
      faceTexture.magFilter = THREE.NearestFilter;
      faceTexture.minFilter = THREE.NearestFilter;
      const faceScreen = new THREE.Mesh(
        new THREE.PlaneGeometry(0.42,0.42 * HOME_FACE_LCD_H / HOME_FACE_LCD_W),
        new THREE.MeshBasicMaterial({map:faceTexture,toneMapped:false}),
      );
      faceScreen.position.set(0,0.22,0.272);
      headPivot.add(faceScreen);

      this._homeRobot3d = {scene,camera,renderer,turntable,headPivot,faceCanvas,faceTexture,currentHeadYaw:0,currentHeadPitch:0,targetHeadYaw:0,targetHeadPitch:0,idle:0};
      this.syncHomeRobotServo();
      this.updateHomeRobotFace();
      const resize = () => {
        const state = this._homeRobot3d;
        if(!state || !host) return;
        const rw = Math.max(180, host.clientWidth || 420);
        const rh = Math.max(180, host.clientHeight || 300);
        state.camera.aspect = rw / rh;
        state.camera.updateProjectionMatrix();
        state.renderer.setSize(rw, rh, false);
      };
      if(typeof ResizeObserver !== 'undefined'){
        this._homeRobotResizeObs = new ResizeObserver(() => resize());
        this._homeRobotResizeObs.observe(host);
      }
      const tick = () => {
        const state = this._homeRobot3d;
        if(!state) return;
        state.idle += 0.016;
        this.syncHomeRobotServo();
        state.currentHeadYaw += (state.targetHeadYaw - state.currentHeadYaw) * 0.16;
        state.currentHeadPitch += (state.targetHeadPitch - state.currentHeadPitch) * 0.16;
        state.headPivot.rotation.order = 'YXZ';
        state.headPivot.rotation.y = state.currentHeadYaw + Math.sin(state.idle * 0.9) * 0.025;
        state.headPivot.rotation.x = state.currentHeadPitch + Math.sin(state.idle * 1.2) * 0.012;
        state.turntable.rotation.y = Math.sin(state.idle * 0.25) * 0.08;
        state.renderer.render(state.scene, state.camera);
        this._homeRobotAnimId = requestAnimationFrame(tick);
      };
      tick();
    },
    animateHomeRobotServo(step){
      const payload = step || {};
      const startX = Number(this.homeRobotServo.x) || HOME_ROBOT_CENTER;
      const startY = Number(this.homeRobotServo.y) || HOME_ROBOT_CENTER;
      const rawX = Number(payload.x);
      const rawY = Number(payload.y);
      const endX = Math.max(0, Math.min(180, payload.xm ? startX + (Number.isFinite(rawX) ? rawX : 0) : (Number.isFinite(rawX) ? rawX : startX)));
      const endY = Math.max(0, Math.min(180, payload.ym ? startY + (Number.isFinite(rawY) ? rawY : 0) : (Number.isFinite(rawY) ? rawY : startY)));
      const duration = Math.max(80, Number(payload.ms) || 420);
      const seq = (this._homeRobotSeq || 0) + 1;
      this._homeRobotSeq = seq;
      return new Promise((resolve) => {
        const t0 = performance.now();
        const frame = () => {
          if(this._homeRobotSeq !== seq){ resolve(); return; }
          const t = Math.min(1, (performance.now() - t0) / duration);
          const eased = 1 - Math.pow(1 - t, 3);
          this.homeRobotServo = {
            x: startX + (endX - startX) * eased,
            y: startY + (endY - startY) * eased,
          };
          if(t < 1) requestAnimationFrame(frame);
          else resolve();
        };
        frame();
      });
    },
    // ── 设备表情模拟：下发表情 / 说话口型 同步到「表情 · 当前」与 3D SIM ──
    simBaseScene(){
      const preview = window.DeskbotFacePreview;
      if(!preview) return null;
      if(this.simScene) return this.simScene; // 已下发表情 → 保持显示直到下次操作
      return preview.pickScene(this.scenes, this.emotionMap, 'idle');
    },
    simFrameIndex(scene){
      const frames = (scene && Array.isArray(scene.frames)) ? scene.frames : [];
      if(!this.simScene || frames.length < 2) return 0; // idle 待机沿用原静态帧
      let total = 0;
      for(const f of frames) total += Math.max(40, Number(f.ms) || 500);
      let t = (this.simNow - this.simSince) % total;
      if(t < 0) t += total;
      for(let i = 0;i < frames.length;i++){
        t -= Math.max(40, Number(frames[i].ms) || 500);
        if(t < 0) return i;
      }
      return 0;
    },
    primitiveBounds(p){
      if(!p || typeof p !== 'object') return null;
      const s = String(p.shape || '').toLowerCase();
      const n = (v) => (Number.isFinite(Number(v)) ? Number(v) : 0);
      if(s === 'line') return {minX:Math.min(n(p.x1),n(p.x2)),minY:Math.min(n(p.y1),n(p.y2)),maxX:Math.max(n(p.x1),n(p.x2)),maxY:Math.max(n(p.y1),n(p.y2))};
      if(s.indexOf('rect') >= 0 || s === 'pixel') return {minX:n(p.x),minY:n(p.y),maxX:n(p.x)+Math.max(1,n(p.w)),maxY:n(p.y)+Math.max(1,n(p.h))};
      if(s.indexOf('circle') >= 0){ const r=n(p.r); return {minX:n(p.x)-r,minY:n(p.y)-r,maxX:n(p.x)+r,maxY:n(p.y)+r}; }
      if(s.indexOf('ellipse') >= 0){ const rw=n(p.rw != null ? p.rw : p.r), rh=n(p.rh != null ? p.rh : p.r); return {minX:n(p.x)-rw,minY:n(p.y)-rh,maxX:n(p.x)+rw,maxY:n(p.y)+rh}; }
      if(s.indexOf('triangle') >= 0){ const xs=[n(p.x0),n(p.x1),n(p.x2)], ys=[n(p.y0),n(p.y1),n(p.y2)]; return {minX:Math.min(...xs),minY:Math.min(...ys),maxX:Math.max(...xs),maxY:Math.max(...ys)}; }
      return null; // text / svg_path 无几何，不参与
    },
    mouthRegion(els){
      // 原 mouth 图层包围盒中心；没有嘴时取双眼底部下方的默认位置
      let minX=Infinity,minY=Infinity,maxX=-Infinity,maxY=-Infinity,any=false;
      for(const p of (Array.isArray(els.mouth) ? els.mouth : [])){
        const b = this.primitiveBounds(p);
        if(!b) continue;
        any = true;
        minX=Math.min(minX,b.minX); minY=Math.min(minY,b.minY); maxX=Math.max(maxX,b.maxX); maxY=Math.max(maxY,b.maxY);
      }
      if(any) return {x:(minX+maxX)/2, y:(minY+maxY)/2, w:Math.max(20,maxX-minX), h:Math.max(4,maxY-minY)};
      let eyeBottom = 0;
      for(const key of ['eye_l','eye_r']){
        for(const p of (Array.isArray(els[key]) ? els[key] : [])){
          const b = this.primitiveBounds(p);
          if(b) eyeBottom = Math.max(eyeBottom, b.maxY);
        }
      }
      return {x:142, y:eyeBottom ? Math.min(200, eyeBottom + 44) : 158, w:30, h:8};
    },
    withTalkMouth(els){
      // 说话口型兜底（无音素行时的旧正弦椭圆）：以原嘴位置为中心的开口椭圆，按音节节奏开合
      const reg = this.mouthRegion(els);
      const now = performance.now();
      const burst = Math.max(0, Math.sin(now * 0.011)); // ≈3Hz 音节
      const frac = burst * burst * (0.55 + 0.45 * Math.abs(Math.sin(now * 0.043)));
      const ry = Math.min(20, Math.max(2, reg.h / 2 + 3 + 14 * frac));
      const rw = Math.max(12, Math.min(46, reg.w / 2 * (1 + 0.3 * frac)));
      return Object.assign({}, els, {mouth:[{shape:'ellipse_fill', x:reg.x, y:reg.y, rw, ry}]});
    },
    talkRowElements(){
      // 按已流逝时间找当前音素表情行（行首端为界）；行已全部播完返回 null
      const rows = this.talkRows;
      if(!Array.isArray(rows) || !rows.length || !Array.isArray(this.talkCums) || !this.talkCums.length) return null;
      const elapsed = Math.max(0, performance.now() - this.talkT0);
      const cums = this.talkCums;
      if(elapsed >= cums[cums.length - 1]) return null;
      let lo = 0, hi = cums.length - 1;
      while(lo < hi){ // 找首个 cums[i] > elapsed
        const mid = (lo + hi) >> 1;
        if(cums[mid] <= elapsed) lo = mid + 1;
        else hi = mid;
      }
      const row = rows[lo];
      const els = row && row.elements;
      return (els && typeof els === 'object') ? els : null;
    },
    faceElsNow(){
      const scene = this.simBaseScene();
      if(!scene) return null;
      const els = window.DeskbotFacePreview.frameElements(scene, this.simFrameIndex(scene));
      if(!els) return null;
      if(this.talkEndsAt != null && performance.now() < this.talkEndsAt){
        // 说话中：优先逐音素表情行（整脸与设备 pb 同款：开口/扁口/圆口…）；
        // 行已播完但仍在窗口边缘 → 保持底稿闭嘴；服务端未返回行(估算失败)时退回旧正弦椭圆口型
        const rowEls = this.talkRowElements();
        if(rowEls) return rowEls;
        if(this.talkRows.length) return els;
        return this.withTalkMouth(els);
      }
      return els;
    },
    bumpSim(){
      this.simNow = performance.now();
      this.updateHomeRobotFace();
    },
    startTalkSim(text, sim){
      // sim = /api/device_tts 响应 talk_sim：{total_ms, rows:[{phoneme,ms,elements}]}
      const rows = Array.isArray(sim && sim.rows)
        ? sim.rows.filter(r => r && r.elements && typeof r.elements === 'object') : [];
      if(rows.length){
        const cums = [];
        let acc = 0;
        for(const r of rows){
          acc += Math.max(20, Number(r.ms) || 100);
          cums.push(acc);
        }
        this.talkRows = rows;
        this.talkCums = cums;
        this.talkT0 = performance.now();
        this.talkEndsAt = this.talkT0 + acc;
      }else{
        // 兜底：无音素行时沿用旧估算时长与正弦口型
        const n = Array.from(String(text || '')).length;
        const ms = Math.max(1800, Math.min(30000, n * 280 + 900)); // ≈0.28s/字 + 首尾余量
        this.talkRows = [];
        this.talkCums = [];
        this.talkEndsAt = performance.now() + ms;
      }
      this._faceLastDraw = 0;
      this.bumpSim();
    },
    simLoop(){
      // 表情动画循环 / 说话口型期间按帧重绘；无模拟内容时静默
      this._homeSimRaf = requestAnimationFrame(() => this.simLoop());
      const now = performance.now();
      const wasTalk = this.talkEndsAt != null;
      if(wasTalk && now >= this.talkEndsAt){ this.talkEndsAt = null; this.talkRows = []; this.talkCums = []; } // 说话结束：下帧闭嘴
      const talking = this.talkEndsAt != null;
      const scene = this.simScene;
      const animated = talking || (!!scene && Array.isArray(scene.frames) && scene.frames.length > 1);
      if(!animated){
        if(wasTalk) this.bumpSim(); // 说完了补一帧闭嘴画面
        return;
      }
      const cadence = talking ? 60 : 120; // 音素行更密，说话时提高重绘频率保证口型切换不跳帧
      if(now - (this._faceLastDraw || 0) >= cadence){
        this._faceLastDraw = now;
        this.simNow = now;
        this.updateHomeRobotFace();
      }
    },
    // ── 快捷下发（实验台简版：仅预置动作 / 预置表情 / 指定文字 TTS）──
    async quickSend(u, opts){
      const r = await fetch(u, opts || {cache:'no-store'});
      let d = {};
      try{ d = await r.json(); }catch(_e){}
      if(!d || d.ok === false){ throw new Error((d && (d.error || d.message)) || ('HTTP ' + r.status)); }
      return d || {};
    },
    async loadQuickControls(){
      this.quick.servo.presets = [];
      this.quick.pb.scenes = [];
      this.quick.pb.selected = '';
      if(!this.bound || !this.deviceId) return;
      const q = '?device_id=' + encodeURIComponent(this.deviceId);
      const sc = await this.j('/api/servo_config' + q);
      const cfg = sc.config || sc;
      this.quick.servo.presets = Array.isArray(cfg.presets) ? cfg.presets : [];
      const ps = await this.j('/api/device_pb_scenes' + q);
      this.quick.pb.scenes = ps.scenes || ps.keys || [];
      if(!this.quick.pb.selected && this.quick.pb.scenes.length){
        const idleIdx = this.quick.pb.scenes.indexOf('idle');
        this.quick.pb.selected = idleIdx >= 0 ? this.quick.pb.scenes[idleIdx] : this.quick.pb.scenes[0];
      }
    },
    pbSceneTitle(s){
      if(!Array.isArray(this.scenes)) return s;
      const row = this.scenes.find(x => String((x && x.name) || '') === s);
      return row ? (row.title || row.name) : s;
    },
    async runQuickServoPreset(p){
      this.quick.msg = '';
      if(!this.bound || !this.deviceId){ this.quick.msg = '请先绑定设备'; return; }
      const steps = (Array.isArray(p.steps) && p.steps.length) ? p.steps : [p];
      const seq = (this._quickSeq || 0) + 1;
      this._quickSeq = seq;
      this.quick.servo.busy = true;
      try{
        for(const step of steps){
          if(this._quickSeq !== seq) return;
          const x = step.x ?? 90, y = step.y ?? 90;
          const u = '/api/device_servo?device_id=' + encodeURIComponent(this.deviceId)
            + '&x=' + x + '&y=' + y + '&dyaw=' + x + '&dpitch=' + y
            + '&xm=' + (step.xm ?? 0) + '&ym=' + (step.ym ?? 0)
            + '&ms=' + (step.ms ?? 500) + '&action=replace';
          await this.quickSend(u);
          await this.animateHomeRobotServo(step); // 3D 形象同步预览
          await new Promise((r) => setTimeout(r, 150)); // 给设备留出执行间隙，避免下一条 replace 打断
        }
        this.quick.msg = '已下发预置动作「' + (p.label || p.id) + '」';
      }catch(e){
        this.quick.msg = e.message || '下发失败';
      }finally{
        this.quick.servo.busy = false;
      }
    },
    async sendQuickPbScene(){
      this.quick.msg = '';
      if(!this.bound || !this.deviceId){ this.quick.msg = '请先绑定设备'; return; }
      if(!this.quick.pb.selected) return;
      this.quick.pb.busy = true;
      try{
        await this.quickSend('/api/device_pb_scene?device_id=' + encodeURIComponent(this.deviceId)
          + '&scene=' + encodeURIComponent(this.quick.pb.selected));
        // 表情与设备同步：模拟显示该表情（多帧循环），直到下次下发
        const row = Array.isArray(this.scenes) ? this.scenes.find(x => String((x && x.name) || '') === this.quick.pb.selected) : null;
        this.simScene = row || null;
        this.simSince = performance.now();
        this.quick.msg = '已下发预置表情「' + (row ? (row.title || row.name) : this.quick.pb.selected) + '」，模拟已同步';
        this.bumpSim();
      }catch(e){
        this.quick.msg = e.message || '下发失败';
      }finally{
        this.quick.pb.busy = false;
      }
    },
    async sendQuickTts(){
      this.quick.msg = '';
      if(!this.bound || !this.deviceId){ this.quick.msg = '请先绑定设备'; return; }
      const text = String(this.quick.tts.text || '').trim();
      if(!text){ this.quick.msg = '请输入要播报的文字'; return; }
      this.quick.tts.busy = true;
      try{
        const d = await this.quickSend('/api/device_tts', {method:'POST',headers:{'Content-Type':'application/json'},
          body:JSON.stringify({device_id:this.deviceId, text:text, want_sim:true})});
        this.quick.msg = 'TTS 已提交下发';
        this.startTalkSim(text, d && d.talk_sim); // 按音素表情行播放口型，估算失败回退旧口型
      }catch(e){
        this.quick.msg = e.message || '下发失败';
      }finally{
        this.quick.tts.busy = false;
      }
    },
    async load(){
      // 电视旋钮：仅记忆本标签页内的开关状态
      try{ this.tvPower = sessionStorage.getItem('home_tv_power') === '1'; }catch(_e){ this.tvPower = false; }
      // 设备
      const dv = await this.j('/app/api/devices');
      const devices = dv.devices || [];
      this.deviceId = dv.current_device_id || '';
      this.bound = !!this.deviceId;
      const cur = devices.find(x => x.device_id === this.deviceId);
      this.deviceName = cur ? (cur.display_name || cur.device_id) : (devices.length ? '未选择' : '未绑定');
      this.scenes = [];
      this.emotionMap = {};
      this.simScene = null; // 表情模拟不跨刷新持久化，回到 idle 映射
      this.simSince = performance.now();
      this.talkEndsAt = null;
      this.talkRows = [];
      this.talkCums = [];
      this.talkT0 = 0;
      // 以下表情数据依赖已选当前设备
      if(this.bound){
        await this.loadQuickControls();
        const q = '?device_id=' + encodeURIComponent(this.deviceId);
        const scenes = await this.j('/api/face_expr_scenes' + q);
        this.scenes = scenes.config || [];
        const em = await this.j('/api/emotion_expr_map' + q);
        this.emotionMap = em.map || {};
      }
      // 设备表情数据就绪后，同步刷新 3D 模型屏幕上的表情，与卡片保持一致
      this.updateHomeRobotFace();
      if(this.tvPower) await this.openHomeCamera(); // 旋钮关闭时不建立摄像头 WS
    },
  },
  mounted(){
    this.setGreeting();
    this.load();
    this.$nextTick(() => { void this.homeRobotInit3d(); });
    this._faceLastDraw = 0;
    this.simLoop();
  },
  beforeUnmount(){
    this.closeHomeCamera();
    this.disposeHomeRobot3d();
    if(this._homeSimRaf) cancelAnimationFrame(this._homeSimRaf);
    if(this.camera.imageUrl) URL.revokeObjectURL(this.camera.imageUrl);
  },
}).mount('#home');
</script>
{% endblock %}

app2c/lab.html:
{% extends "base_2c.html" %}
{% block page_title %}设备实验台 · 小歪{% endblock %}
{% block global_setup_suppress_device %}1{% endblock %}
{% block extra_head %}
<script src="{{ url_for('static', filename='vendor/vue.global.prod.min.js') }}"></script>
<style>
  .lab-main{max-width:1024px;margin:0 auto}
  .lab-panel{border:var(--bw) solid var(--line);border-radius:var(--r);background:var(--panel);padding:14px;box-shadow:var(--shadow);min-width:0;margin-bottom:14px}
  .lab-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;margin-bottom:12px}
  .lab-head b{display:block;font-size:16px}
  .lab-head small,.lab-note{display:block;color:var(--dim);font-size:12px;line-height:1.45}
  .ws-status{font-family:var(--mono);font-size:11px;color:var(--dim);white-space:nowrap}
  .ws-status.on{color:var(--accent)}
  .hist-chat{display:grid;gap:18px;height:60vh;min-height:320px;overflow:auto;padding:6px 4px}
  .hist-turn{display:grid;gap:10px}
  .hist-bubble{max-width:86%;padding:10px 12px;border-radius:var(--r);border:var(--bw) solid var(--line);box-shadow:var(--shadow-sm)}
  .hist-bubble.bot{background:var(--panel2);justify-self:start;border-bottom-left-radius:2px}
  .hist-bubble.user{background:var(--panel);justify-self:end;border-bottom-right-radius:2px;border-color:var(--accent)}
  .hist-meta{font-size:11px;color:var(--dim);font-family:var(--mono);margin-bottom:6px;display:flex;flex-wrap:wrap;gap:4px}
  .hist-text{margin:0 0 6px;font-size:13px;line-height:1.5;white-space:pre-wrap;word-break:break-word}
  .hist-tools{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:6px}
  .tool-chip{font-size:11px;font-family:var(--mono);background:var(--panel);border:var(--bw) solid var(--line);border-radius:var(--r);padding:2px 8px;cursor:help}
  .convo-call{display:grid;gap:5px;margin:6px 0;padding:6px 8px;border:var(--bw) solid var(--line);border-radius:var(--r);background:var(--panel)}
  .convo-call-head{display:flex;flex-wrap:wrap;gap:6px;align-items:center}
  .convo-chip{display:inline-flex;align-items:center;font-size:11px;font-family:var(--mono);background:var(--panel2);border:var(--bw) solid var(--line);border-radius:var(--r);padding:2px 8px;white-space:nowrap}
  .convo-chip.dim{color:var(--dim)}
  .convo-call-text{margin:0}
  .convo-details{margin-top:2px}
  .convo-details summary{cursor:pointer;font-size:11px;font-family:var(--mono);color:var(--accent)}
  .convo-details p{max-height:260px;overflow:auto}
  .convo-details pre{max-height:320px;overflow:auto;margin:4px 0 0;padding:8px;border:var(--bw) solid var(--line);border-radius:6px;background:var(--panel);white-space:pre-wrap;word-break:break-all;font-family:var(--mono);font-size:11px;line-height:1.5}
  .convo-audio{display:block;width:100%;height:34px;margin:2px 0 4px;border:var(--bw) solid var(--line);border-radius:6px;background:var(--panel2)}
  .convo-face{display:block;max-width:220px;max-height:170px;border:var(--bw) solid var(--line);border-radius:6px;background:#111;margin:2px 0 4px}
  .hist-turn.live{opacity:.92}
  .hist-turn.live .hist-bubble{border-style:dashed}
  .live-dot{color:var(--accent);animation:live-pulse 1.2s ease-in-out infinite}
  @keyframes live-pulse{0%,100%{opacity:.35}50%{opacity:1}}
  .hist-error{color:#d92d20}
</style>
{% endblock %}
{% block content %}
<div id="labApp">
  <div class="pagehd">
    <div>
      <div class="eyebrow">LAB · LIVE CONVO</div>
      <h1>设备实验台</h1>
      <p>实时对话调试台：订阅设备流水（ASR / LLM / TTS / 视觉 / 声纹），逐轮展示模型、耗时与媒体回放。其余设备控制已移入「家」。</p>
    </div>
    <div class="btngroup">
      <select v-model="currentDeviceId" @change="switchDevice">
        <option value="">选择设备</option>
        <option v-for="d in devices" :key="d.device_id" :value="d.device_id">[[ d.display_name ]] · [[ d.device_id ]]</option>
      </select>
      <button type="button" class="btn ghost" @click="refresh">刷新</button>
    </div>
  </div>

  <p class="lead" v-if="msg">[[ msg ]]</p>

  <div class="lab-main">
    <div class="lab-panel">
      <div class="lab-head">
        <div>
          <b>实时对话</b>
          <small>WS 实时订阅 + /api/pipeline_recent 初始加载（窗口 100 条，仅本会话内存保留）。只显示对话轮次；每条消息展示 ASR / LLM / TTS 的模型与耗时（人脸 / 声纹识别单独显示识别耗时），LLM 多次调用逐条列出（输出过长可展开，每条默认折叠展示引擎原始返回 JSON）。用户气泡内含本轮 System Prompt 与机器人看到的画面 / 图像识别 / 声纹识别（均可折叠）；ASR 原声与 TTS 合成音可回放（媒体仅内存保留，过期后自动隐藏）。</small>
        </div>
        <span class="ws-status" :class="{on: pipeline.status==='connected'}">[[ wsLabelText() ]]</span>
      </div>
      <small class="lab-note">接口：/api/pipeline_recent · /api/pipeline_audio · /device_pipeline（role=subscriber）</small>
    </div>

    <div class="lab-panel">
      <div class="lab-head"><div><b>对话记录</b><small>按时间升序 · 实时刷新 · 仅本会话内存保留。机器人左对齐 · 用户右对齐。</small></div></div>
      <div class="hist-chat" ref="histChat" @scroll="onHistScroll">
        <template v-if="convoTurns.length">
          <div v-for="t in convoTurns" :key="'row_'+t.request_id" class="hist-turn" :class="{live: !t.final}">
            <div class="hist-bubble user">
              <div class="hist-meta" v-if="t.asr_model || (t.asr_ms !== null && t.asr_ms !== undefined) || t.audio_asr">
                <span class="convo-chip">🎤 ASR</span>
                <span v-if="t.asr_model" class="convo-chip dim">[[ t.asr_model ]]</span>
                <span v-if="t.asr_ms !== null && t.asr_ms !== undefined" class="convo-chip dim">[[ fmtMs(t.asr_ms) ]]</span>
                <span v-if="t.received_ts" class="dim">· [[ tsText(t.received_ts) ]]</span>
              </div>
              <p v-if="t.asr_text" class="hist-text">[[ t.asr_text ]]</p>
              <audio v-if="t.audio_asr" v-show="!t.asrAudioFail" class="convo-audio" controls preload="none" :src="mediaSrc(t,'asr')" @error="onAudioFail(t,'asr')"></audio>
              <div v-if="t.face_img || t.face_sight" class="convo-call">
                <div class="convo-call-head">
                  <span class="convo-chip">🧑 视觉</span>
                  <span v-if="t.face_sight" class="convo-chip dim">图像识别</span>
                  <span v-if="t.face_ms !== null && t.face_ms !== undefined" class="convo-chip dim">识别耗时 [[ msText(t.face_ms) ]]</span>
                  <span v-if="t.face_img" class="convo-chip dim">最近一帧</span>
                </div>
                <img v-if="t.face_img" v-show="!t.imgFail" class="convo-face" :src="mediaSrc(t,'face')" @error="onAudioFail(t,'face')" alt="该轮人脸画面">
                <p v-if="t.face_sight" class="hist-text convo-call-text">[[ t.face_sight ]]</p>
              </div>
              <div v-if="t.voice_sight" class="convo-call">
                <div class="convo-call-head">
                  <span class="convo-chip">🎙 声音</span>
                  <span class="convo-chip dim">声纹识别</span>
                  <span v-if="t.voice_ms !== null && t.voice_ms !== undefined" class="convo-chip dim">识别耗时 [[ msText(t.voice_ms) ]]</span>
                </div>
                <p class="hist-text convo-call-text">[[ t.voice_sight ]]</p>
              </div>
              <details v-if="t.system_prompt" class="convo-call convo-details">
                <summary>📝 System Prompt（系统提示词 · 本轮输入）</summary>
                <p class="hist-text convo-call-text">[[ t.system_prompt ]]</p>
              </details>
            </div>
            <div class="hist-bubble bot">
              <div class="hist-meta">
                <span v-if="t.e2e_ms !== null && t.e2e_ms !== undefined" class="dim">⏱ 总耗时 [[ fmtMs(t.e2e_ms) ]]</span>
                <span v-if="t.llm_ms !== null && t.llm_ms !== undefined && !(t.llm_calls && t.llm_calls.length)">🤖 LLM 整轮 [[ fmtMs(t.llm_ms) ]]</span>
                <span v-if="t.source">· [[ sourceLabel(t.source) ]]</span>
                <span v-if="t.received_ts" class="dim">· [[ tsText(t.received_ts) ]]</span>
                <span v-if="t.note">[[ t.note ]]</span>
                <span v-if="!t.final" class="live-dot">进行中…</span>
              </div>
              <div v-if="t.llm_calls && t.llm_calls.length" class="convo-calls">
                <div v-for="(call, i) in t.llm_calls" :key="'llm_'+i" class="convo-call">
                  <div class="convo-call-head">
                    <span class="convo-chip">🤖 LLM #[[ call.n ]]</span>
                    <span v-if="call.model" class="convo-chip dim">[[ call.model ]]</span>
                    <span class="convo-chip dim">[[ fmtMs(call.ms) ]]</span>
                  </div>
                  <template v-if="call.text">
                    <p class="hist-text dim convo-call-text">[[ llmCallPreview(call) ]]<template v-if="call.text.length > 180">…</template></p>
                    <details v-if="call.text.length > 180" class="convo-details">
                      <summary>展开完整调用输出（[[ call.text.length ]] 字）</summary>
                      <p class="hist-text">[[ call.text ]]</p>
                    </details>
                  </template>
                  <details v-if="call.raw" class="convo-details">
                    <summary>🧾 原始返回（引擎原文 JSON<span v-if="call.raw_truncated"> · 已截断</span>）</summary>
                    <pre>[[ prettyRaw(call.raw) ]]</pre>
                  </details>
                </div>
              </div>
              <div v-if="t.tools && t.tools.length" class="hist-tools">
                <span v-for="(tool, i) in t.tools" :key="i" class="tool-chip" :title="json(tool.args)">🔧 [[ toolName(tool) ]]</span>
              </div>
              <p v-if="t.llm_text" class="hist-text">[[ t.llm_text ]]</p>
              <p v-if="t.tts_text && t.tts_text !== t.llm_text" class="hist-text dim">🗣 [[ t.tts_text ]]</p>
              <div v-if="t.tts_ms !== null && t.tts_ms !== undefined || t.tts_text" class="convo-call">
                <div class="convo-call-head">
                  <span class="convo-chip">🔊 TTS</span>
                  <span v-if="t.tts_model" class="convo-chip dim">[[ t.tts_model ]]</span>
                  <span class="convo-chip dim">[[ fmtMs(t.tts_ms) ]]</span>
                </div>
                <audio v-if="t.audio_tts" v-show="!t.ttsAudioFail" class="convo-audio" controls preload="none" :src="mediaSrc(t,'tts')" @error="onAudioFail(t,'tts')"></audio>
              </div>
              <p v-if="t.error" class="hist-text hist-error">⚠ [[ t.error ]]</p>
            </div>
          </div>
        </template>
        <p v-else class="lab-note">暂无对话。选择设备并开启一轮对话后，实时显示在这里。</p>
      </div>
    </div>
  </div>
</div>
{% endblock %}
{% block scripts %}
<script>
const { createApp } = Vue;
/** WS 基址与当前页面 host 对齐（避免用 127.0.0.1 打开页面却连局域网 IP）。 */
function alignWsBaseToPageHost(base) {
  const raw = String(base || '').trim();
  if (!raw) return raw;
  try {
    const u = new URL(raw);
    if (window.location.hostname) u.hostname = window.location.hostname;
    return u.toString().replace(/\/$/, '');
  } catch (_) { return raw; }
}
createApp({
  delimiters:['[[',']]'],
  data(){ return {
    msg:'',
    devicePipelineWsBase: alignWsBaseToPageHost({{ device_pipeline_ws_base|tojson }}),
    devices:[], currentDeviceId:'',
    pipeline:{ws:null,status:'',retry:0,retryTimer:null},
    convo:{rows:{}},
    // 实时对话：新消息到达是否自动滚到底部（用户上翻查看历史时暂停跟随）
    convoFollowBottom:true,
  }; },
  computed:{
    convoTurns(){
      return Object.values(this.convo.rows).sort((a,b)=>(a.ts||0)-(b.ts||0));
    },
  },
  watch:{
    'convo.rows':{deep:true,handler(){ if(this.convoFollowBottom) this.$nextTick(this.scrollHistToBottom); }},
  },
  methods:{
    json(v){ return JSON.stringify(v || {}, null, 2); },
    async api(url, opts){
      const r=await fetch(url, opts||{cache:'no-store'});
      const d=await r.json().catch(()=>({ok:false,error:'响应解析失败'}));
      if(!r.ok || d.ok===false) throw new Error(d.error||d.message||('HTTP '+r.status));
      return d;
    },
    proxyPath(path, params){
      const url = new URL(path, window.location.origin);
      if(this.currentDeviceId) url.searchParams.set('device_id', this.currentDeviceId);
      for(const [k,v] of Object.entries(params||{})){
        if(v !== undefined && v !== null && String(v) !== '') url.searchParams.set(k, v);
      }
      return url.toString();
    },
    requireDevice(options){
      const silent = !!(options && options.silent);
      if(!this.currentDeviceId){
        if(!silent) this.msg='请先选择设备';
        return false;
      }
      return true;
    },
    wsLabelText(){
      return ({connecting:'连接中…', connected:'实时连接中', closed:'已断开 · 自动重连', error:'连接异常'})[this.pipeline.status] || '未连接';
    },
    async loadDevices(){
      const d=await this.api('/app/api/devices');
      this.devices=d.devices||[];
      this.currentDeviceId=d.current_device_id || (this.devices[0] && this.devices[0].device_id) || '';
    },
    async refresh(){
      try{
        await this.loadDevices();
        this.msg='';
        if(this.currentDeviceId){
          this.closePipeline();
          this.ensurePipelineWs();
          this.loadConvoRecent();
        }
      }catch(e){ this.msg=e.message||'刷新失败'; }
    },
    async switchDevice(){
      await this.api('/app/api/devices/select',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({device_id:this.currentDeviceId})});
      this.msg=this.currentDeviceId ? '已切换当前设备' : '已清空当前设备';
      this.convo.rows={};
      this.closePipeline();
      await this.loadDevices();
      this.ensurePipelineWs();
      this.loadConvoRecent();
    },
    // ── 实时对话 ──
    async loadConvoRecent(){
      if(!this.requireDevice()) return;
      try{
        const d=await this.api(this.proxyPath('/api/pipeline_recent', {limit:100}));
        for(const it of (d.items||[])){
          if(!it || !it.request_id) continue;
          if('stage' in it) this.applyStage(it);
          else if('e2e_ms' in it) this.applyPipeEvent(it);
        }
      }catch(e){ this.msg=e.message||'加载实时对话失败'; }
    },
    closePipeline(){
      if(this.pipeline.retryTimer){ clearTimeout(this.pipeline.retryTimer); this.pipeline.retryTimer=null; }
      if(this.pipeline.ws){ try{ this.pipeline.ws.onclose=null; this.pipeline.ws.close(); }catch(_e){} this.pipeline.ws=null; }
      this.pipeline.status='closed';
    },
    ensurePipelineWs(){
      if(!this.requireDevice()) return;
      if(this._pipelineClosed) return;
      if(this.pipeline.ws && (this.pipeline.ws.readyState===0 || this.pipeline.ws.readyState===1)) return;
      try{
        const url=new URL(this.devicePipelineWsBase);
        // 必须带 role=subscriber：不带会被服务端当作生产者抢占设备连接槽位，
        // 把设备的真实 asr_chat 连接踢掉，导致两连接互相踢的反复重连
        url.searchParams.set('role', 'subscriber');
        url.searchParams.set('device_id', this.currentDeviceId);
        this.pipeline.status='connecting';
        const ws=new WebSocket(url.toString());
        this.pipeline.ws=ws;
        ws.onopen=()=>{ this.pipeline.retry=0; this.pipeline.status='connected'; };
        ws.onclose=()=>{
          this.pipeline.ws=null; this.pipeline.status='closed';
          if(!this._pipelineClosed){
            const delay=Math.min(30000, 1000*Math.pow(2, this.pipeline.retry));
            this.pipeline.retry+=1;
            this.pipeline.retryTimer=setTimeout(()=>this.ensurePipelineWs(), delay);
          }
        };
        ws.onerror=()=>{ /* 由 onclose 统一触发退避重连 */ };
        ws.onmessage=(ev)=>{ this.onPipelineFrame(ev); };
      }catch(_e){ this.pipeline.status='error'; }
    },
    onPipelineFrame(ev){
      let frame=null;
      try{ frame=JSON.parse(ev.data); }catch(_e){ frame=null; }
      if(frame && frame.type==='pipeline_snapshot'){ this.onPipelineSnapshot(frame.items||[]); }
      else if(frame && frame.type==='pipeline_stage' && frame.event){ this.applyStage(frame.event); }
      else if(frame && frame.type==='pipeline_event' && frame.event){ this.applyPipeEvent(frame.event); }
    },
    applyStage(evt){
      const rid=evt.request_id;
      if(!rid || evt.device_id!==this.currentDeviceId) return;
      // 工具轮过渡 / 错误兜底的辅助 stage（无完成事件对应）显式忽略
      if(/_interim_|_llm_err/.test(String(rid))) return;
      const row=this.convo.rows[rid] || {request_id:rid, ts:(evt.ts||Date.now()/1000)};
      row.stage=evt.stage;
      if(evt.received_ts) row.received_ts=evt.received_ts;
      if(evt.voice_auto_reply_off){ row.final=true; row.note='自动应答已关闭'; }
      if(evt.asr_text!==undefined) row.asr_text=evt.asr_text;
      if(evt.asr_ms!==undefined) row.asr_ms=evt.asr_ms;
      if(evt.asr_model!==undefined) row.asr_model=evt.asr_model;
      if(evt.llm_text!==undefined) row.llm_text=evt.llm_text;
      if(evt.llm_ms!==undefined) row.llm_ms=evt.llm_ms;
      if(evt.llm_calls!==undefined) row.llm_calls=evt.llm_calls;
      if(evt.tts_text!==undefined) row.tts_text=evt.tts_text;
      if(evt.tts_ms!==undefined) row.tts_ms=evt.tts_ms;
      if(evt.tts_model!==undefined) row.tts_model=evt.tts_model;
      if(evt.audio_asr!==undefined) row.audio_asr=evt.audio_asr;
      if(evt.audio_tts!==undefined) row.audio_tts=evt.audio_tts;
      if(evt.face_img!==undefined) row.face_img=evt.face_img;
      if(evt.face_sight!==undefined) row.face_sight=evt.face_sight;
      if(evt.voice_sight!==undefined) row.voice_sight=evt.voice_sight;
      if(evt.face_ms!==undefined) row.face_ms=evt.face_ms;
      if(evt.voice_ms!==undefined) row.voice_ms=evt.voice_ms;
      if(evt.system_prompt!==undefined) row.system_prompt=evt.system_prompt;
      if(evt.source!==undefined) row.source=evt.source;
      this.convo.rows[rid]=row;
    },
    applyPipeEvent(evt){
      const rid=evt.request_id;
      if(!rid || evt.device_id!==this.currentDeviceId) return;
      if('stage' in evt){ this.applyStage(evt); return; } // pub 冗余帧，幂等
      if('e2e_ms' in evt){ // 轮次完成：合并进现有行，气泡保留在实时对话中
        const row=this.convo.rows[rid] || {request_id:rid, ts:(evt.received_ts||Date.now()/1000)};
        row.final=true;
        row.e2e_ms=evt.e2e_ms;
        row.status=evt.status||'ok';
        if(evt.error!==undefined) row.error=evt.error;
        if(evt.tools!==undefined) row.tools=evt.tools;
        if(evt.asr_text!==undefined) row.asr_text=evt.asr_text;
        if(evt.asr_ms!==undefined) row.asr_ms=evt.asr_ms;
        if(evt.asr_model!==undefined) row.asr_model=evt.asr_model;
        if(evt.llm_text!==undefined) row.llm_text=evt.llm_text;
        if(evt.llm_ms!==undefined) row.llm_ms=evt.llm_ms;
        if(evt.llm_calls!==undefined) row.llm_calls=evt.llm_calls;
        if(evt.tts_text!==undefined) row.tts_text=evt.tts_text;
        if(evt.tts_ms!==undefined) row.tts_ms=evt.tts_ms;
        if(evt.tts_model!==undefined) row.tts_model=evt.tts_model;
        if(evt.audio_asr!==undefined) row.audio_asr=evt.audio_asr;
        if(evt.audio_tts!==undefined) row.audio_tts=evt.audio_tts;
        if(evt.face_img!==undefined) row.face_img=evt.face_img;
        if(evt.face_sight!==undefined) row.face_sight=evt.face_sight;
        if(evt.voice_sight!==undefined) row.voice_sight=evt.voice_sight;
        if(evt.face_ms!==undefined) row.face_ms=evt.face_ms;
        if(evt.voice_ms!==undefined) row.voice_ms=evt.voice_ms;
        if(evt.system_prompt!==undefined) row.system_prompt=evt.system_prompt;
        if(evt.source!==undefined) row.source=evt.source;
        if(evt.received_ts) row.received_ts=evt.received_ts;
        if(evt.voice_auto_reply_off) row.note='自动应答已关闭';
        this.convo.rows[rid]=row;
      }
    },
    onPipelineSnapshot(items){
      for(const it of (items||[])){
        if(!it || !it.request_id || it.device_id!==this.currentDeviceId) continue;
        if('stage' in it) this.applyStage(it);
        else if('e2e_ms' in it) this.applyPipeEvent(it);
      }
      // 只清理长时间未完成的进行中行；已完成气泡保留整个会话（内存）
      const now=Date.now()/1000;
      for(const rid of Object.keys(this.convo.rows)){
        const row=this.convo.rows[rid];
        if(!row.final && now-(row.ts||now)>300) delete this.convo.rows[rid];
      }
    },
    toolName(t){ return (t && (t.tool || t.name)) || '工具'; },
    sourceLabel(s){ return ({asr:'语音', text:'文本', device_tts:'设备 TTS', scheduled_task:'定时任务'})[s] || s || ''; },
    llmCallPreview(call){
      const txt=(call && call.text) || '';
      return txt.length>180 ? txt.slice(0,180) : txt;
    },
    // 识别耗时固定以 ms 显示（人脸/声纹识别），不套用 fmtMs 的 s 换算
    msText(v){
      if(v===null || v===undefined) return '-';
      return Math.round(Number(v))+'ms';
    },
    // 引擎原始返回：合法 JSON 文本则美化缩进展示，否则原样显示
    prettyRaw(raw){
      if(!raw) return '';
      if(typeof raw !== 'string') raw=JSON.stringify(raw, null, 2);
      try{ return JSON.stringify(JSON.parse(raw), null, 2); }
      catch(_e){ return raw; }
    },
    mediaSrc(t, kind){
      return this.proxyPath('/api/pipeline_audio', {request_id: t && t.request_id, kind});
    },
    onAudioFail(t, kind){
      if(!t) return;
      if(kind==='asr') t.asrAudioFail=1;
      else if(kind==='tts') t.ttsAudioFail=1;
      else if(kind==='face') t.imgFail=1;
    },
    onHistScroll(e){
      const el=(e && e.target) || this.$refs.histChat;
      if(!el) return;
      // 距底部 60px 内视为跟随模式；上翻查看历史时暂停自动滚动
      this.convoFollowBottom = (el.scrollHeight - el.scrollTop - el.clientHeight) < 60;
    },
    scrollHistToBottom(){
      const el=this.$refs.histChat;
      if(el) el.scrollTop=el.scrollHeight;
    },
    // 对话区高度延伸到窗口底部（不超界），最大化聊天可视范围
    resizeConvo(){
      const el=this.$refs.histChat;
      if(!el) return;
      const gap=16; // 距窗口底部留白
      const h=Math.max(320, window.innerHeight - el.getBoundingClientRect().top - gap);
      el.style.height=h+'px';
      el.style.maxHeight=h+'px';
    },
    onWinResize(){
      this.resizeConvo();
    },
    fmtMs(v){ if(v===null || v===undefined) return '-'; v=Number(v); if(v>=1000) return (v/1000).toFixed(3)+'s'; return v+'ms'; },
    tsText(ts){ if(!ts) return ''; const d=new Date(ts*1000); const p=n=>String(n).padStart(2,'0'); return p(d.getMonth()+1)+'-'+p(d.getDate())+' '+p(d.getHours())+':'+p(d.getMinutes()); },
  },
  async mounted(){
    await this.loadDevices();
    this.$nextTick(()=>{ this.ensurePipelineWs(); this.loadConvoRecent(); this.resizeConvo(); });
    window.addEventListener('resize', this.onWinResize);
  },
  beforeUnmount(){
    window.removeEventListener('resize', this.onWinResize);
    this._pipelineClosed=true;
    this.closePipeline();
  },
}).mount('#labApp');
</script>
{% endblock %}

