{% extends "base_2c.html" %}
{% block page_title %}记忆 · 小歪{% endblock %}
{% block extra_head %}<script src="{{ url_for('static', filename='vendor/vue.global.prod.min.js') }}"></script>{% endblock %}
{% block content %}
<div id="app">
  <div class="pagehd"><div><div class="eyebrow">MEMORY · [[ items.length ]] ENTRIES</div><h1>记忆</h1><p>机器人记住的关于你的小事，随时可改可删。</p></div></div>
  <div style="display:flex;gap:8px;margin-bottom:18px;max-width:560px" v-if="!noDevice">
    <input class="tinput" v-model="draft" placeholder="加一条它该记住的事…" @keyup.enter="add">
    <button :disabled="!!busyAction" class="btn primary" @click="add">＋ 加一条</button>
  </div>
  <div class="colwrap">
    <div class="note" v-for="(m,i) in items" :key="m.id">
      <span class="memtag">MEM_[[ String(i+1).padStart(2,'0') ]]</span>
      <textarea v-if="editing===m.id" class="tinput editarea" v-model="editText" @keyup.meta.enter="saveEdit(m)" @keyup.ctrl.enter="saveEdit(m)"></textarea>
      <p v-else>[[ m.text ]]</p>
      <small>[[ m.created_at_fmt || '' ]]</small>
      <div class="btngroup" style="margin-top:12px">
        <template v-if="editing===m.id">
          <button :disabled="!!busyAction" class="btn primary" @click="saveEdit(m)">保存</button>
          <button :disabled="!!busyAction" class="btn ghost" @click="cancelEdit">取消</button>
        </template>
        <template v-else>
          <button :disabled="!!busyAction" class="btn ghost" @click="startEdit(m)">编辑</button>
          <button :disabled="!!busyAction" class="btn ghost" @click="del(m)">删除</button>
        </template>
      </div>
    </div>
  </div>
  <p v-if="loading" role="status">正在读取数据…</p>
  <p v-if="!loading && noDevice">请先在顶栏选择设备。</p>
  <button v-if="loadError" class="btn" @click="load">重试加载</button>
  <p v-if="busyAction" role="status">正在处理，请稍候…</p>
  <p class="lead" v-if="msg">[[ msg ]]</p>
</div>
{% endblock %}
{% block scripts %}
<script>
const { createApp } = Vue;
createApp({
  delimiters:['[[',']]'],
  data(){ return { items:[], draft:'', msg:'', editing:'', editText:'', noDevice:false }; },
  methods:{
    async load(){
      const d=await (await fetch('/app/api/devices')).json();
      this.noDevice = !d.current_device_id;
      if(this.noDevice){ this.items=[]; return; }
      const r=await (await fetch('/app/api/memories')).json();
      if(r.ok) this.items=r.memories||[]; else this.msg=r.error||'加载失败'; },
    async add(){ const t=this.draft.trim(); if(!t) return;
      const r=await (await fetch('/app/api/memories',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text:t})})).json();
      if(r.ok){ this.draft=''; this.msg='已添加记忆'; this.load(); } else this.msg=r.error||'添加失败'; },
    startEdit(m){ this.editing=m.id; this.editText=m.text||''; },
    cancelEdit(){ this.editing=''; this.editText=''; },
    async saveEdit(m){ const t=this.editText.trim(); if(!t){ this.msg='记忆内容不能为空'; return; }
      const r=await (await fetch('/app/api/memories/'+m.id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({text:t})})).json();
      if(r.ok){ this.cancelEdit(); this.msg='已保存记忆'; this.load(); } else this.msg=r.error||'保存失败'; },
    async del(m){ const r=await (await fetch('/app/api/memories/'+m.id,{method:'DELETE'})).json();
      if(r.ok){ this.msg='已删除记忆'; this.load(); } else this.msg=r.error||'删除失败'; },
  },
  mounted(){ this.load(); },
}).mount('#app');
</script>
{% endblock %}

