{% macro icon(name) -%}
{% if name == 'home' %}<svg viewBox="0 0 24 24"><path d="M3 11l9-8 9 8"/><path d="M5 10v10h14V10"/></svg>
{% elif name == 'expr' %}<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><path d="M8.5 14c1 1.3 6 1.3 7 0"/><circle cx="9" cy="10" r="1"/><circle cx="15" cy="10" r="1"/></svg>
{% elif name == 'lab' %}<svg viewBox="0 0 24 24"><path d="M8 3v5l-4 8a4 4 0 003.6 5h8.8A4 4 0 0020 16l-4-8V3"/><path d="M9 3h6"/><path d="M7 14h10"/><path d="M10 17h4"/></svg>
{% elif name == 'memory' %}<svg viewBox="0 0 24 24"><path d="M6 3h12a1 1 0 011 1v16l-7-4-7 4V4a1 1 0 011-1z"/></svg>
{% elif name == 'remind' %}<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></svg>
{% elif name == 'people' %}<svg viewBox="0 0 24 24"><circle cx="12" cy="8" r="4"/><path d="M4 20c0-4 4-6 8-6s8 2 8 6"/></svg>
{% elif name == 'users' %}<svg viewBox="0 0 24 24"><circle cx="9" cy="8" r="3.4"/><path d="M3 20c0-3.4 2.7-5.4 6-5.4s6 2 6 5.4"/><circle cx="16.8" cy="9.4" r="2.5"/><path d="M16.4 14.6c2.7.4 4.6 2.2 4.6 5.4"/></svg>
{% elif name == 'device' %}<svg viewBox="0 0 24 24"><rect x="6" y="3" width="12" height="18" rx="2"/><path d="M11 18h2"/></svg>
{% elif name == 'miot' %}<svg viewBox="0 0 24 24"><path d="M4 10h16v10H4z"/><path d="M8 10V7a4 4 0 018 0v3"/><path d="M12 14v3"/></svg>
{% elif name == 'advanced' %}<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="3"/><path d="M19.4 13a7 7 0 000-2l2-1.5-2-3.4-2.3 1a7 7 0 00-1.7-1L15 3h-4l-.7 2.6a7 7 0 00-1.7 1l-2.3-1-2 3.4L4.6 11a7 7 0 000 2l-2 1.5 2 3.4 2.3-1a7 7 0 001.7 1L11 21h4l.7-2.6a7 7 0 001.7-1l2.3 1 2-3.4z"/></svg>
{% elif name == 'service' %}<svg viewBox="0 0 24 24"><rect x="3" y="3" width="18" height="18" rx="3"/><rect x="8.5" y="8.5" width="7" height="7" rx="1.5"/></svg>
{% elif name == 'flash' %}<svg viewBox="0 0 24 24"><rect x="7" y="4" width="10" height="16" rx="2"/><path d="M9 8h6M9 12h6"/><path d="M4 10v4M20 10v4"/></svg>
{% elif name == 'quest' %}<svg viewBox="0 0 24 24"><path d="M6 3h12a1 1 0 011 1v17l-3-2-3 2-3-2-3 2V4a1 1 0 011-1z"/><path d="M9 8h6"/><path d="M9 12h6"/><path d="M9 16h4"/></svg>
{% elif name == 'robot' %}<svg viewBox="0 0 24 24"><rect x="5" y="8" width="14" height="10" rx="3"/><circle cx="9.5" cy="13" r="1.2"/><circle cx="14.5" cy="13" r="1.2"/><path d="M12 8V5"/><circle cx="12" cy="4" r="1"/><path d="M9 16h6"/></svg>
{% endif %}
{%- endmacro %}
<!DOCTYPE html>
<html lang="zh-CN">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>{% block page_title %}小歪 · 专属于你的桌面机器人{% endblock %}</title>
  <link rel="icon" type="image/svg+xml" href="{{ url_for('static', filename='favicon.svg') }}">
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;500;600;700&family=Space+Mono:wght@400;700&display=swap" rel="stylesheet">
  <link rel="stylesheet" href="{{ url_for('static', filename='theme_2c.css') }}?v=20260910-clear-device-data">
  {% block extra_head %}{% endblock %}
</head>
<body>
<div class="shell">
  <!-- ===== topbar ===== -->
  <div class="topbar">
    <div class="tb-l">
      <a class="tb-brand" href="{{ url_for('app2c.home') }}" style="text-decoration:none">
        <span class="tb-mark">歪</span>
        <span class="tb-name">BRUFIK</span>
        <span class="tb-sub">CONSOLE</span>
      </a>
      <span class="tb-div"></span>
      <div class="tb-devwrap" id="tbDevWrap">
        <div class="tb-devsel" id="tbDevSel" title="切换当前设备">
          <span class="led" id="tbDevLed"></span><span id="tbDevLabel">检查中…</span><span class="caret">▾</span>
        </div>
        <div class="tb-devpanel" id="tbDevPanel">
          <div class="tb-devhead">已绑定设备 · 点击切换</div>
          <div id="tbDevList"><div class="tb-dev-empty">检查中…</div></div>
        </div>
      </div>
      <span class="tb-div"></span>
      <button type="button" class="btn ghost" id="tbDevManage" style="padding:7px 12px">管理</button>
      <button type="button" class="btn ghost" id="tbDevBind" style="padding:7px 12px">＋ 绑定新设备</button>
    </div>
    <div class="tb-r">
      <span class="tb-clock" id="tbClock">--:--:--</span>
      <form method="post" action="{{ url_for('auth.logout') }}">
        <button type="submit" class="btn ghost" style="padding:7px 12px">退出</button>
      </form>
    </div>
  </div>

  <div class="app">
    <aside class="side">
      <div class="brand"><div class="logo">歪</div><div><b>小歪</b><small>专属于你的桌面机器人</small></div></div>
      <nav class="navi">
        <a href="{{ url_for('app2c.home') }}" class="navlink {{ 'on' if active_nav=='home' }}">{{ icon('home') }}家</a>
        <div class="lbl">我的小歪</div>
        <a href="{{ url_for('robot_settings.page') }}" class="navlink {{ 'on' if active_nav=='robot_settings' }}">{{ icon('robot') }}机器人配置</a>
        <a href="{{ url_for('app2c.lab') }}" class="navlink {{ 'on' if active_nav=='lab' }}">{{ icon('lab') }}实验台</a>
        <a href="{{ url_for('flash.flash_page') }}" class="navlink {{ 'on' if active_nav=='flash' }}">{{ icon('flash') }}烧录固件</a>
        <div class="lbl">日常</div>
        <a href="{{ url_for('app2c.memories') }}" class="navlink {{ 'on' if active_nav=='memory' }}">{{ icon('memory') }}记忆</a>
        <a href="{{ url_for('app2c.reminders') }}" class="navlink {{ 'on' if active_nav=='remind' }}">{{ icon('remind') }}提醒</a>
        <a href="{{ url_for('app2c.people') }}" class="navlink {{ 'on' if active_nav=='people' }}">{{ icon('people') }}认识的人</a>
        <a href="{{ url_for('app2c.miot') }}" class="navlink {{ 'on' if active_nav=='miot' }}">{{ icon('miot') }}米家</a>
        {% if nav_is_developer %}
        <div class="lbl">开发者选项</div>
        <a href="{{ url_for('app2c.expr') }}" class="navlink {{ 'on' if active_nav=='expr' }}">{{ icon('expr') }}表情设计</a>
        <a href="{{ url_for('quest.page') }}" class="navlink {{ 'on' if active_nav=='quest' }}">{{ icon('quest') }}剧情设计</a>
        <a href="{{ url_for('debug.dev_users_page') }}" class="navlink {{ 'on' if active_nav=='users' }}">{{ icon('users') }}用户管理</a>
        {% endif %}
        <div class="gap"></div>
        <a href="{{ url_for('app2c.advanced') }}" class="navlink {{ 'on' if active_nav=='advanced' }}">{{ icon('advanced') }}账户</a>
      </nav>
      <div class="foot"><div class="userchip"><div class="ua">歪</div><div><b>{{ nav_display_name or '我' }}</b><small>{{ nav_user_email or '' }}</small></div></div></div>
    </aside>
    <main>
      <div
        id="globalSetup"
        class="global-setup"
        data-suppress-device="{% block global_setup_suppress_device %}0{% endblock %}"
        hidden
      ></div>
      {% block content %}{% endblock %}
    </main>
  </div>
</div>

<!-- 顶栏设备管理对话框 -->
<div class="modal-overlay" id="tbManageModal" hidden>
  <div class="modal-panel">
    <div class="modal-hd"><b>设备管理</b><button type="button" class="close">✕</button></div>
    <div class="modal-bd">
      <table class="devtable">
        <thead>
          <tr><th>设备 ID</th><th>是否在线</th><th>最近同步时间</th><th>操作</th></tr>
        </thead>
        <tbody id="tbManageTbody"></tbody>
      </table>
      <div class="modal-msg" id="tbManageMsg"></div>
    </div>
  </div>
</div>

<!-- 顶栏清除设备数据二次确认对话框 -->
<div class="modal-overlay" id="tbWipeModal" hidden>
  <div class="modal-panel small">
    <div class="modal-hd"><b>清除设备数据</b><button type="button" class="close">✕</button></div>
    <div class="modal-bd">
      <p class="wipe-lead">将永久删除 <b id="tbWipeId">—</b> 的全部云端数据，且不可恢复：</p>
      <ul class="wipe-list">
        <li>长期记忆与对话记录</li>
        <li>人脸档案与人声纹档案</li>
        <li>定时提醒任务</li>
        <li>剧本任务进度</li>
        <li>米家绑定与授权</li>
        <li>设备配置文件（舵机/场景等）</li>
        <li>用量统计</li>
      </ul>
      <div class="modal-msg" id="tbWipeMsg"></div>
    </div>
    <div class="modal-ft">
      <button type="button" class="btn ghost" id="tbWipeCancel">取消</button>
      <button type="button" class="btn danger" id="tbWipeOk">确认清除</button>
    </div>
  </div>
</div>

<!-- 顶栏绑定新设备对话框 -->
<div class="modal-overlay" id="tbBindModal" hidden>
  <div class="modal-panel small">
    <div class="modal-hd"><b>绑定新设备</b><button type="button" class="close">✕</button></div>
    <div class="modal-bd">
      <input class="tinput" id="tbBindInput" placeholder="设备 ID，例如 brfk_aabbccddeeff1234" autocomplete="off">
      <p class="bind-hint">设备开机联网后，屏幕上会显示它的 device_id。设备须在线且未被其他账号绑定才能绑定成功。</p>
      <div class="modal-msg" id="tbBindMsg"></div>
    </div>
    <div class="modal-ft">
      <button type="button" class="btn ghost" id="tbBindCancel">取消</button>
      <button type="button" class="btn primary" id="tbBindOk">绑定</button>
    </div>
  </div>
</div>
<script data-shell>
  (function(){
    var el=document.getElementById('tbClock'); if(!el) return;
    var p=function(n){return String(n).padStart(2,'0');};
    var tick=function(){var d=new Date();el.textContent=p(d.getHours())+':'+p(d.getMinutes())+':'+p(d.getSeconds());};
    tick(); setInterval(tick,1000);
  })();
  (function(){
    // 顶栏设备选择器：下拉显示设备列表（在线状态 + 最近访问），点击即切换当前设备；
    // 管理对话框可删除（解绑）设备，绑定对话框负责新增设备。
    var wrap=document.getElementById('tbDevWrap');
    if(!wrap) return;
    var led=document.getElementById('tbDevLed'), label=document.getElementById('tbDevLabel');
    var panel=document.getElementById('tbDevPanel'), list=document.getElementById('tbDevList');
    var manageBtn=document.getElementById('tbDevManage'), bindBtn=document.getElementById('tbDevBind');
    var manageModal=document.getElementById('tbManageModal'), bindModal=document.getElementById('tbBindModal');
    var manageMsg=document.getElementById('tbManageMsg'), bindMsg=document.getElementById('tbBindMsg');
    var bindInput=document.getElementById('tbBindInput'), bindOk=document.getElementById('tbBindOk');
    var wipeModal=document.getElementById('tbWipeModal'), wipeMsg=document.getElementById('tbWipeMsg');
    var wipeId=document.getElementById('tbWipeId'), wipeOk=document.getElementById('tbWipeOk');
    var wipeCancel=document.getElementById('tbWipeCancel');
    var state={devices:[],current:'',wipeTarget:''};
    var esc=function(s){return String(s||'').replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});};
    var short=function(t){ return (t==='—'||!t)?'—':String(t).slice(5,16); }; // YYYY-MM-DD HH:MM:SS → MM-DD HH:MM

    function currentDevice(){
      for(var i=0;i<state.devices.length;i++) if(state.devices[i].device_id===state.current) return state.devices[i];
      return null;
    }
    function renderTrigger(){
      if(!state.devices.length){ led.className='led off'; label.textContent='未绑定设备'; return; }
      var cur=currentDevice();
      if(!cur){ led.className='led off'; label.textContent='未选择设备'; return; }
      led.className=cur.online?'led':'led off';
      label.textContent=cur.online ? cur.device_id+' · LINK·OK' : cur.device_id+' · 离线';
    }
    function renderList(){
      if(!state.devices.length){ list.innerHTML='<div class="tb-dev-empty">还没有绑定设备，点击右侧「＋ 绑定新设备」</div>'; return; }
      list.innerHTML=state.devices.map(function(d){
        var offCls=d.online?'':' off';
        return '<div class="tb-devrow" data-id="'+esc(d.device_id)+'">'
          +'<span class="led'+offCls+'"></span>'
          +'<span class="did">'+esc(d.device_id)+'</span>'
          +(d.device_id===state.current?'<span class="tag">当前</span>':'')
          +'<span class="meta"><b class="'+offCls.trim()+'">'+(d.online?'在线':'离线')+'</b><small>访问 '+esc(short(d.last_seen))+'</small></span>'
          +'</div>';
      }).join('');
      var rows=list.querySelectorAll('.tb-devrow');
      for(var i=0;i<rows.length;i++){
        rows[i].addEventListener('click', function(){ select(this.getAttribute('data-id')); });
      }
    }
    function renderManage(){
      var tbody=document.getElementById('tbManageTbody');
      if(!tbody) return;
      if(!state.devices.length){
        tbody.innerHTML='<tr><td colspan="4" class="empty">还没有绑定设备</td></tr>';
        return;
      }
      tbody.innerHTML=state.devices.map(function(d){
        return '<tr>'
          +'<td class="did">'+esc(d.device_id)+'</td>'
          +'<td><span class="led'+(d.online?'':' off')+'"></span>'+(d.online?'在线':'离线')+'</td>'
          +'<td class="st">'+esc(d.last_sync)+'</td>'
          +'<td><span class="devrow-actions">'
          +'<button type="button" class="btn danger" data-del="'+esc(d.device_id)+'">删除</button>'
          +'<button type="button" class="btn danger" data-wipe="'+esc(d.device_id)+'">清除数据</button>'
          +'</span></td>'
          +'</tr>';
      }).join('');
      var btns=tbody.querySelectorAll('[data-del]');
      for(var i=0;i<btns.length;i++){
        btns[i].addEventListener('click', function(){
          removeDevice(this.getAttribute('data-del'));
        });
      }
      var wipes=tbody.querySelectorAll('[data-wipe]');
      for(var i=0;i<wipes.length;i++){
        wipes[i].addEventListener('click', function(){
          openWipe(this.getAttribute('data-wipe'));
        });
      }
    }
    function load(){
      fetch('/app/api/devices').then(function(r){return r.json();}).then(function(d){
        if(d.ok){ state.devices=d.devices||[]; state.current=d.current_device_id||''; }
        renderTrigger(); renderList(); renderManage();
      }).catch(function(){ led.className='led off'; label.textContent='状态未知'; });
    }
    function select(id){
      if(id===state.current) return;
      void DeskbotUI.switchDevice(id).then(function(ok){ if(ok){wrap.classList.remove('open');load();} });
    }
    function removeDevice(id){
      if(!confirm('确定删除（解绑）设备 '+id+'？解绑后当前账号将无法再看到这台设备。')) return;
      fetch('/app/api/devices/'+encodeURIComponent(id),{method:'DELETE'}).then(function(r){return r.json();}).then(function(d){
        if(d.ok){
          if(manageMsg){ manageMsg.className='modal-msg ok'; manageMsg.textContent='已解绑 '+id; }
          if(id===DeskbotUI.device)void DeskbotUI.reloadDevice('');else load();
        }else{
          if(manageMsg){ manageMsg.className='modal-msg err'; manageMsg.textContent=d.error||'删除失败'; }
        }
      }).catch(function(){
        if(manageMsg){ manageMsg.className='modal-msg err'; manageMsg.textContent='网络错误，请重试'; }
      });
    }
    // 清除数据：站内二次确认（危险操作，默认焦点落在「取消」，且不绑 Enter 提交）
    function openWipe(id){
      id=id||''; if(!id) return;
      state.wipeTarget=id;
      wipeId.textContent=id;
      wipeMsg.className='modal-msg'; wipeMsg.textContent='';
      wipeModal.hidden=false;
      wipeCancel.focus();
    }
    function closeWipe(){
      wipeModal.hidden=true;
      wipeMsg.className='modal-msg'; wipeMsg.textContent='';
      state.wipeTarget='';
    }
    function clearDeviceData(){
      var id=state.wipeTarget; if(!id) return;
      wipeOk.disabled=true;
      fetch('/app/api/devices/'+encodeURIComponent(id)+'/data',{method:'DELETE'})
        .then(function(r){return r.json();}).then(function(d){
          if(d.ok){
            closeWipe();
            var x=d.deleted||{};
            if(manageMsg){
              manageMsg.className='modal-msg ok';
              manageMsg.textContent='已清除 '+id+' 的云端数据（记忆 '+(x.memory|0)
                +' / 人脸 '+(x.face_profiles|0)+' / 声纹 '+(x.voice_profiles|0)
                +' / 对话 '+(x.sessions|0)+' 段 '+(x.session_messages|0)+' 条'
                +' / 提醒 '+(x.scheduled_tasks|0)+' / 剧本 '+(x.quest_instances|0)
                +' / 用量 '+(x.usage_rows|0)+'）';
            }
            load();
          }else{
            wipeMsg.className='modal-msg err'; wipeMsg.textContent=d.error||'清除失败';
          }
        }).catch(function(){
          wipeMsg.className='modal-msg err'; wipeMsg.textContent='网络错误，请重试';
        }).finally(function(){ wipeOk.disabled=false; });
    }
    function doBind(){
      var id=bindInput.value.trim();
      if(!id){ bindMsg.className='modal-msg err'; bindMsg.textContent='请输入 device_id'; return; }
      bindOk.disabled=true;
      fetch('/app/api/devices',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({device_id:id})})
        .then(function(r){return r.json();}).then(function(d){
          if(d.ok){
            bindModal.hidden=true; bindMsg.textContent=''; bindInput.value='';
            void DeskbotUI.switchDevice(d.current_device_id || id);
          }else{
            bindMsg.className='modal-msg err'; bindMsg.textContent=d.error||'绑定失败';
          }
        }).catch(function(){
          bindMsg.className='modal-msg err'; bindMsg.textContent='网络错误，请重试';
        }).finally(function(){ bindOk.disabled=false; });
    }
    // 下拉开关：点触发器展开/收起，点外部收起
    document.getElementById('tbDevSel').addEventListener('click', function(e){
      e.stopPropagation();
      wrap.classList.toggle('open');
    });
    document.addEventListener('click', function(){ wrap.classList.remove('open'); });
    // 管理对话框
    manageBtn.addEventListener('click', function(){ renderManage(); manageModal.hidden=false; });
    manageModal.addEventListener('click', function(e){ if(e.target===manageModal) manageModal.hidden=true; });
    manageModal.querySelector('.close').addEventListener('click', function(){ manageModal.hidden=true; });
    // 清除数据对话框：遮罩 / ✕ / 取消 关闭（不绑 Esc，与其余对话框一致）
    wipeModal.addEventListener('click', function(e){ if(e.target===wipeModal) closeWipe(); });
    wipeModal.querySelector('.close').addEventListener('click', closeWipe);
    wipeCancel.addEventListener('click', closeWipe);
    wipeOk.addEventListener('click', clearDeviceData);
    // 绑定对话框
    bindBtn.addEventListener('click', function(){ bindMsg.textContent=''; bindModal.hidden=false; bindInput.focus(); });
    bindModal.addEventListener('click', function(e){ if(e.target===bindModal) bindModal.hidden=true; });
    bindModal.querySelector('.close').addEventListener('click', function(){ bindModal.hidden=true; });
    bindModal.querySelector('#tbBindCancel').addEventListener('click', function(){ bindModal.hidden=true; });
    bindOk.addEventListener('click', doBind);
    bindInput.addEventListener('keydown', function(e){ if(e.key==='Enter') doBind(); });
    window.addEventListener('deskbot:device-changed', load);
    load();
    setInterval(load, 15000); // 周期刷新在线状态与最近时间
  })();
  (function(){
    var box=document.getElementById('globalSetup'); if(!box) return;
    var esc=function(s){return String(s||'').replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});};
    var item=function(kind,title,body,href,label){
      return '<a class="global-setup-item '+kind+'" href="'+esc(href)+'">'
        + '<span class="global-setup-dot"></span>'
        + '<span class="global-setup-copy"><b>'+esc(title)+'</b><small>'+esc(body)+'</small></span>'
        + '<span class="global-setup-action">'+esc(label)+'</span>'
        + '</a>';
    };
    var suppressDevice=String(box.getAttribute('data-suppress-device')||'').trim()==='1';
    fetch('/app/api/devices').then(function(r){return r.json();}).catch(function(){return {};}).then(function(devicesPayload){
      devicesPayload=devicesPayload||{};
      var html=[];
      var devices=devicesPayload.devices||[];
      var currentId=devicesPayload.current_device_id||'';
      if(!suppressDevice && !devices.length){
        html.push(item(
          'device',
          '还没绑定专属于你的桌面机器人小歪',
          '绑定第一台小歪后，表情、声音、记忆和提醒才会同步到设备。',
          '{{ url_for("app2c.devices") }}',
          '去绑定'
        ));
      }else if(!suppressDevice && !currentId){
        html.push(item(
          'device',
          '还没选择当前小歪',
          '从已绑定设备里选择一台，控制台配置会同步到这台设备。',
          '{{ url_for("app2c.devices") }}',
          '去选择'
        ));
      }
      if(html.length){
        box.innerHTML=html.join('');
        box.hidden=false;
      }
    });
  })();
</script>
{% block scripts %}{% endblock %}
</body>
</html>

debug_llm.html:
{% extends "base.html" %}
{% block page_title %}LLM 调试 · Deskbot Server{% endblock %}
{% block extra_head %}
  <script>
    window.__LLM_INFO__ = {
      model: {{ llm_model|tojson }},
      baseUrl: {{ llm_base_url|tojson }},
      systemPrompt: {{ llm_system_prompt|tojson }},
      planAppendix: {{ llm_plan_appendix|tojson }},
      currentDeviceId: {{ current_device_id|tojson }},
      ownedDevices: {{ owned_device_rows|tojson }},
    };
  </script>
  <script src="{{ url_for('static', filename='vendor/vue.global.prod.min.js') }}"></script>
{% endblock %}
{% block content %}
  <h1>LLM 调试</h1>
  <p class="sub">
    直接调用当前生效的大模型配置（优先设备级模型；系统默认使用火山方舟，API Key 来自
    <code>ARK_API_KEY</code> / <code>VOLCENGINE_API_KEY</code> / <code>LLM_API_KEY</code>）；纯文本对话，不走 ASR/TTS，
    用于快速验证各设备独立的 system prompt 与模型回答效果。对话模型直接输出口语纯文本，
    动作/表情由独立的决策模型负责（见下方「决策模型 Prompt」）。
  </p>
  {% raw %}
  <div id="app" class="llm-debug">
    <div class="card meta">
      <div class="meta-row">
        <span class="lbl">当前设备</span>
        <span class="val mono">{{ deviceId || "（未选择）" }}</span>
        <span v-if="!deviceId" class="muted sm warn-tag">请先在顶部「我的设备」中选择</span>
      </div>
      <div class="meta-row">
        <span class="lbl">模型</span>
        <span class="val mono">{{ info.model || "(未配置)" }}</span>
      </div>
      <div class="meta-row">
        <span class="lbl">Base URL</span>
        <span class="val mono">{{ info.baseUrl || "(未配置)" }}</span>
      </div>
      <details class="meta-row sys-prompt" :open="sysOpen" @toggle="sysOpen = $event.target.open">
        <summary>
          System Prompt
          <span class="muted sm" v-if="sysDirty">（已修改，未保存）</span>
          <span class="muted sm" v-else>（来自 data/device/{{ deviceId || "…" }}/llm_system.txt）</span>
        </summary>
        <textarea v-model="systemPrompt" rows="12" class="sys-ta" placeholder="编辑当前设备的 system prompt" :disabled="!deviceId"></textarea>
        <div class="sys-actions">
          <button type="button" class="btn-light" @click="resetSystemPrompt" :disabled="!sysDirty || !deviceId">撤销修改</button>
          <button type="button" class="btn-light" @click="saveSystemPrompt" :disabled="!deviceId || savingPrompt">
            {{ savingPrompt ? "保存中…" : "保存到设备" }}
          </button>
          <span class="muted sm" v-if="saveMsg">{{ saveMsg }}</span>
          <span class="muted sm">提交时会自动追加「当前时间」、长期记忆与工具 directive 附录，与线上一致；动作/表情不在对话 prompt 中。</span>
        </div>
      </details>
      <details class="meta-row plan-appendix" :open="appendixOpen" @toggle="appendixOpen = $event.target.open">
        <summary>决策模型 Prompt / 请求（动作 / 表情白名单，只读）</summary>
        <pre class="appendix-pre">{{ planAppendix || "（暂无附录，请检查 data/servo.json 与 data/deskbot-face.json）" }}</pre>
      </details>
      <div class="meta-row controls">
        <label class="lbl">温度</label>
        <input v-model.number="temperature" type="number" min="0" max="2" step="0.1" class="num-input" />
        <button type="button" class="btn-light" @click="clearChat" :disabled="!turns.length && !pending">清空对话</button>
        <span class="muted sm">已发 {{ turnCount }} 轮 · 上下文 {{ historyMessageCount }} 条消息</span>
      </div>
    </div>

    <div class="layout-chat">
      <div class="chat-panel" ref="chatBox">
        <p v-if="!turns.length && !pending" class="empty">在下方输入文字开始与 LLM 对话；当前会话内会保留多轮上下文。</p>
        <div v-for="t in turns" :key="t.id" class="turn">
          <div v-if="t.errNotice" class="bubble bubble-sys">{{ t.errNotice }}</div>
          <template v-else>
            <div class="bubble bubble-user">
              <div class="src">用户</div>
              <div class="txt">{{ t.userText }}</div>
            </div>
            <div
              v-if="t.assistantText || t.error || t.pending"
              :class="['bubble', t.error ? 'bubble-sys' : 'bubble-assistant']"
            >
              <div class="src">{{ t.error ? '错误' : '助手' }}</div>
              <div v-if="t.pending" class="txt muted">…思考中</div>
              <div v-else-if="t.error" class="txt">{{ t.error }}</div>
              <template v-else>
                <div class="txt">{{ t.assistantText }}</div>
                <div v-if="t.moves && t.moves.length" class="actions-row">
                  <span class="lbl">动作 gesture</span>
                  <span v-for="(m, mi) in t.moves" :key="'m'+mi" class="action-chip">{{ chipText(m, 'move') }}</span>
                </div>
                <div v-if="t.anims && t.anims.length" class="actions-row">
                  <span class="lbl">表情 expression</span>
                  <span v-for="(a, ai) in t.anims" :key="'a'+ai" class="action-chip anim">{{ chipText(a, 'anim') }}</span>
                </div>
                <details v-if="t.raw && (t.raw !== t.assistantText || !t.jsonOk)" class="raw-block">
                  <summary>
                    原始输出
                    <span v-if="!t.jsonOk" class="warn-tag">JSON 解析失败</span>
                  </summary>
                  <pre class="raw-pre">{{ t.raw }}</pre>
                </details>
              </template>
              <div v-if="!t.pending && !t.error && (t.elapsedMs != null || t.usage)" class="ts">
                <span v-if="t.elapsedMs != null">耗时: {{ t.elapsedMs }} ms</span>
                <span v-if="t.usage && t.usage.total_tokens != null" class="sep">· tokens: {{ t.usage.total_tokens }}</span>
                <span v-if="t.usage && t.usage.prompt_tokens != null" class="sep">(prompt {{ t.usage.prompt_tokens }} / completion {{ t.usage.completion_tokens }})</span>
              </div>
            </div>
          </template>
        </div>
      </div>

      <div class="composer">
        <div class="row-text">
          <textarea
            v-model="draft"
            rows="2"
            placeholder="输入文字后发送；Enter 发送，Shift+Enter 换行"
            @keydown="onDraftKey"
            class="ta"
            :disabled="pending"
          ></textarea>
          <button type="button" class="btn-send" :disabled="!canSend" @click="send">
            {{ pending ? "发送中…" : "发送" }}
          </button>
        </div>
      </div>
    </div>
  </div>
  <style>
    .sub { color: #6e6e73; font-size: 14px; line-height: 1.5; margin-bottom: 12px; }
    .llm-debug { width: 100%; max-width: none; }
    .meta { padding: 12px 16px; }
    .meta-row { display: flex; align-items: center; gap: 8px; margin-bottom: 8px; flex-wrap: wrap; }
    .meta-row:last-child { margin-bottom: 0; }
    .meta-row .lbl { color: #6e6e73; font-size: 13px; min-width: 72px; }
    .meta-row .val { font-size: 13px; word-break: break-all; }
    .mono { font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 12px; }
    .sys-prompt, .plan-appendix { width: 100%; flex-direction: column; align-items: stretch; }
    .sys-prompt summary, .plan-appendix summary { cursor: pointer; color: #1d1d1f; font-size: 13px; user-select: none; width: 100%; }
    .sys-prompt summary::-webkit-details-marker, .plan-appendix summary::-webkit-details-marker { display: none; }
    .sys-ta { display: block; width: 100%; box-sizing: border-box; margin: 6px 0 0; padding: 8px 10px; font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 12px; line-height: 1.5; border: 1px solid #c7c7cc; border-radius: 6px; resize: vertical; min-height: 160px; background: #fbfbfd; }
    .appendix-pre { display: block; width: 100%; box-sizing: border-box; margin: 6px 0 0; padding: 8px 10px; font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 12px; line-height: 1.5; border: 1px solid #e5e5ea; border-radius: 6px; background: #f5f5f7; white-space: pre-wrap; word-break: break-word; max-height: 280px; overflow: auto; }
    .sys-actions { display: flex; align-items: center; gap: 10px; margin-top: 6px; flex-wrap: wrap; width: 100%; }
    .controls { gap: 10px; }
    .device-select { min-width: 220px; padding: 6px 8px; border: 1px solid #c7c7cc; border-radius: 6px; font-size: 13px; }
    .num-input { width: 76px; padding: 6px 8px; border: 1px solid #c7c7cc; border-radius: 6px; }
    .btn-light { padding: 6px 12px; border: 1px solid #c7c7cc; background: #fff; border-radius: 6px; cursor: pointer; font-size: 13px; }
    .btn-light:hover:not(:disabled) { background: #f5f5f7; }
    .btn-light:disabled { opacity: 0.5; cursor: not-allowed; }
    .layout-chat { display: flex; flex-direction: column; gap: 0; width: 100%; }
    .chat-panel {
      border: 1px solid #d2d2d7;
      border-radius: 10px;
      background: #e8e8ed;
      min-height: 280px;
      max-height: min(60vh, 600px);
      overflow-y: auto;
      padding: 12px 14px;
      width: 100%;
      box-sizing: border-box;
    }
    .empty { text-align: center; color: #6e6e73; font-size: 14px; margin: 2rem 0; }
    .turn { margin-bottom: 12px; }
    .turn:last-child { margin-bottom: 0; }
    .bubble { border-radius: 12px; padding: 10px 12px; max-width: 92%; font-size: 14px; margin-bottom: 6px; }
    .bubble:last-child { margin-bottom: 0; }
    .bubble .src { font-size: 11px; text-transform: uppercase; letter-spacing: 0.04em; color: #6e6e73; margin-bottom: 4px; }
    .bubble .txt { white-space: pre-wrap; word-break: break-word; line-height: 1.5; }
    .bubble .txt.muted { color: #6e6e73; font-style: italic; }
    .bubble .ts { font-size: 12px; color: #6e6e73; margin-top: 6px; }
    .sep { margin-left: 0.2em; }
    .bubble-user { background: #d1e7ff; margin-left: 12%; }
    .bubble-assistant { background: #fff; border: 1px solid #d2d2d7; }
    .bubble-sys { background: #fff3cd; border: 1px solid #e6d89c; color: #665; font-size: 13px; }
    .actions-row { margin-top: 8px; display: flex; align-items: center; flex-wrap: wrap; gap: 6px; }
    .actions-row .lbl { color: #6e6e73; font-size: 12px; margin-right: 2px; }
    .action-chip {
      display: inline-block;
      padding: 2px 8px;
      border-radius: 999px;
      background: #e9f4ff;
      border: 1px solid #b8dafe;
      color: #0a4d8c;
      font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
      font-size: 12px;
    }
    .action-chip.anim { background: #f3e9ff; border-color: #d4b8fe; color: #5a2d91; }
    .raw-block { margin-top: 8px; }
    .raw-block summary { cursor: pointer; color: #6e6e73; font-size: 12px; user-select: none; }
    .raw-block summary::-webkit-details-marker { display: none; }
    .raw-pre { white-space: pre-wrap; word-break: break-word; background: #f5f5f7; border: 1px solid #e5e5ea; border-radius: 6px; padding: 8px 10px; font-size: 12px; line-height: 1.5; max-height: 240px; overflow: auto; margin: 6px 0 0; font-family: ui-monospace, SFMono-Regular, Menlo, monospace; }
    .warn-tag { color: #b42318; font-size: 12px; margin-left: 6px; }
    .composer { margin-top: 12px; width: 100%; }
    .row-text { display: flex; gap: 8px; align-items: flex-end; width: 100%; }
    .ta { flex: 1; padding: 8px 10px; border: 1px solid #c7c7cc; border-radius: 6px; resize: vertical; min-height: 52px; font-family: inherit; font-size: 14px; }
    .btn-send { padding: 8px 18px; border-radius: 6px; border: 1px solid #c7c7cc; background: #fff; cursor: pointer; flex-shrink: 0; }
    .btn-send:hover:not(:disabled) { background: #f5f5f7; }
    .btn-send:disabled { opacity: 0.5; cursor: not-allowed; }
    .muted { color: #6e6e73; font-size: 12px; }
    .sm { font-size: 12px; }
  </style>
  <script>
    if (!window.Vue) {
      const mount = document.getElementById("app");
      if (mount) {
        mount.innerHTML = '<div class="bubble bubble-sys">前端依赖 Vue 加载失败，请检查静态资源是否到位。</div>';
      }
    } else {
    const { createApp } = Vue;

    createApp({
      data() {
        const info = window.__LLM_INFO__ || {
          model: "", baseUrl: "", systemPrompt: "", planAppendix: "",
          currentDeviceId: "", ownedDevices: [],
        };
        return {
          info,
          ownedDevices: info.ownedDevices || [],
          deviceId: info.currentDeviceId || "",
          defaultSystemPrompt: info.systemPrompt || "",
          systemPrompt: info.systemPrompt || "",
          planAppendix: info.planAppendix || "",
          sysOpen: true,
          appendixOpen: true,
          turns: [],
          draft: "",
          pending: false,
          savingPrompt: false,
          saveMsg: "",
          nextId: 0,
          temperature: 0.7,
        };
      },
      computed: {
        sysDirty() {
          return (this.systemPrompt || "") !== (this.defaultSystemPrompt || "");
        },
        canSend() {
          return !this.pending && !!this.draft.trim() && !!this.deviceId;
        },
        turnCount() {
          return this.turns.filter((t) => !t.errNotice && t.assistantText).length;
        },
        history() {
          const out = [];
          for (const t of this.turns) {
            if (t.errNotice || t.error || t.pending) continue;
            if (t.userText) out.push({ role: "user", content: t.userText });
            const asst = t.raw || t.assistantText;
            if (asst) out.push({ role: "assistant", content: asst });
          }
          return out;
        },
        historyMessageCount() {
          return this.history.length;
        },
      },
      watch: { turns: { deep: true, handler() { this._scrollEnd(); } } },
      methods: {
        // gesture/expression 条目：新协议为字符串 id，旧协议为 {move/anim, ms} 对象
        chipText(item, key) {
          if (typeof item === "string") return item;
          const name = item?.[key] || "?";
          return item?.ms ? `${name} · ${item.ms}ms` : name;
        },
        _scrollEnd() {
          this.$nextTick(() => {
            const el = this.$refs.chatBox;
            if (el) el.scrollTop = el.scrollHeight;
          });
        },
        onDraftKey(e) {
          if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); this.send(); }
        },
        clearChat() {
          this.turns = [];
        },
        resetSystemPrompt() {
          this.systemPrompt = this.defaultSystemPrompt || "";
          this.saveMsg = "";
        },
        async onDeviceChange() {
          this.saveMsg = "";
          if (!this.deviceId) return;
          try {
            const res = await fetch(`/api/llm/system_prompt?device_id=${encodeURIComponent(this.deviceId)}`);
            const data = await res.json().catch(() => ({}));
            if (!res.ok || !data.ok) {
              this.saveMsg = data.error || `加载失败 HTTP ${res.status}`;
              return;
            }
            this.defaultSystemPrompt = data.system_prompt || "";
            this.systemPrompt = this.defaultSystemPrompt;
          } catch (e) {
            this.saveMsg = `加载失败：${e?.message || e}`;
          }
        },
        async saveSystemPrompt() {
          if (!this.deviceId || this.savingPrompt) return;
          this.savingPrompt = true;
          this.saveMsg = "";
          try {
            const res = await fetch("/api/llm/system_prompt", {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({
                device_id: this.deviceId,
                system_prompt: this.systemPrompt,
              }),
            });
            const data = await res.json().catch(() => ({}));
            if (!res.ok || !data.ok) {
              this.saveMsg = data.error || `保存失败 HTTP ${res.status}`;
              return;
            }
            this.defaultSystemPrompt = data.system_prompt || this.systemPrompt;
            this.systemPrompt = this.defaultSystemPrompt;
            this.saveMsg = "已保存到设备目录";
          } catch (e) {
            this.saveMsg = `保存失败：${e?.message || e}`;
          } finally {
            this.savingPrompt = false;
          }
        },
        async send() {
          const text = (this.draft || "").trim();
          if (!text || this.pending) return;
          const history = this.history;
          const turn = {
            id: ++this.nextId,
            userText: text,
            assistantText: "",
            moves: [],
            anims: [],
            raw: "",
            jsonOk: false,
            pending: true,
            error: "",
            elapsedMs: null,
            usage: null,
          };
          this.turns.push(turn);
          this.draft = "";
          this.pending = true;
          try {
            const res = await fetch("/api/llm/chat", {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({
                text,
                history,
                temperature: this.temperature,
                system_prompt: this.systemPrompt,
                device_id: this.deviceId,
              }),
            });
            const data = await res.json().catch(() => ({}));
            if (!res.ok || !data.ok) {
              turn.error = data.error || `HTTP ${res.status}`;
            } else {
              turn.assistantText = data.reply || "";
              turn.moves = Array.isArray(data.moves) ? data.moves : [];
              turn.anims = Array.isArray(data.anims) ? data.anims : [];
              turn.raw = data.raw || "";
              turn.jsonOk = !!data.json_ok;
              turn.elapsedMs = data.elapsed_ms;
              turn.usage = data.usage || null;
            }
          } catch (e) {
            turn.error = `网络异常：${e?.message || e}`;
          } finally {
            turn.pending = false;
            this.pending = false;
          }
        },
      },
      mounted() {
        if (this.deviceId) void this.onDeviceChange();
        this._onGlobalDeviceChange = (e) => {
          const id = (e && e.detail && e.detail.device_id) || window.__CURRENT_DEVICE_ID__ || "";
          if (id === this.deviceId) return;
          this.deviceId = id;
          this.turns = [];
          void this.onDeviceChange();
        };
        window.addEventListener("deskbot:device-changed", this._onGlobalDeviceChange);
      },
      unmounted() {
        if (this._onGlobalDeviceChange) {
          window.removeEventListener("deskbot:device-changed", this._onGlobalDeviceChange);
        }
      },
    }).mount("#app");
    }
  </script>
  {% endraw %}
{% endblock %}

debug_online.html:
{% extends "base.html" %}
{% block page_title %}在线调试 · Deskbot Server{% endblock %}
{% block extra_head %}
  <script>window.__DESKBOT_WS_DEFAULT__ = {{ deskbot_ws_default|tojson }};</script>
  <script src="{{ url_for('static', filename='vendor/vue.global.prod.min.js') }}"></script>
{% endblock %}
{% block content %}
  <h1>在线调试</h1>
  <p class="sub">与 Deskbot Server 建立 WebSocket 后，可用麦克风说一句话（服务端 VAD 分句）或直接输入文字；对话以聊天气泡展示，回复含 LLM 文本与可点播放的 TTS 音频。耗时来自服务端 <code>t_mono</code>。</p>
  {% raw %}
  <div id="app" class="online-debug">
    <div class="toolbar">
      <label class="t-label">WebSocket</label>
      <input v-model="wsUrl" :disabled="connected" class="t-ws" />
      <button type="button" @click="toggleConn">{{ connected ? "断开" : "连接" }}</button>
      <span :class="['t-status', connected ? 'ok' : 'bad']">{{ statusText }}</span>
    </div>
    <p v-if="!connected" class="warn">请先连接。跨机访问时请把地址中的主机名改为可路由的 IP。</p>

    <div class="layout-chat">
      <div class="chat-panel" ref="chatBox">
        <p v-if="!turns.length" class="empty">暂无消息。连接后使用下方麦克风或文本输入开始对话。</p>
        <div v-for="t in turns" :key="t.id" class="turn">
          <div v-if="t.errNotice" class="bubble bubble-sys">{{ t.errNotice }}</div>
          <template v-else>
            <div v-if="t.rejected" class="bubble bubble-sys">已忽略：未通过文本过滤（<span class="mono">{{ t.rejectedText }}</span>）</div>
            <template v-else>
              <div class="bubble bubble-user" v-if="t.userText != null">
                <div class="src">{{ t.userSource === 'text' ? '键入' : 'ASR' }}</div>
                <div class="txt">{{ t.userText }}</div>
                <div v-if="t.userAudioUrl" class="row-audio">
                  <span class="lbl">用户音频</span>
                  <audio :src="t.userAudioUrl" controls preload="none" class="audio-ctrl"></audio>
                  <a :href="t.userAudioUrl" :download="t.userAudioName || ('user-' + t.id + '.wav')" class="btn-file">下载</a>
                </div>
                <div class="ts" v-if="t.asrMs != null && t.userSource === 'asr'">ASR: {{ t.asrMs }} ms</div>
              </div>
              <div
                v-if="t.assistantText || t.audioUrl || t.ttsErr || t.srvErr"
                class="bubble bubble-assistant"
              >
                <div class="src">助手</div>
                <div v-if="t.assistantText" class="txt">{{ t.assistantText }}</div>
                <div v-if="t.ttsErr" class="err-line">TTS: {{ t.ttsErr }}</div>
                <div v-if="t.srvErr" class="err-line">错误: {{ t.srvErr }}</div>
                <div v-if="t.audioUrl" class="row-audio">
                  <span class="lbl">回复音频</span>
                  <audio :src="t.audioUrl" controls preload="none" class="audio-ctrl"></audio>
                  <a :href="t.audioUrl" :download="t.audioName || ('assistant-' + t.id + '.wav')" class="btn-file">下载</a>
                </div>
                <div class="ts" v-if="hasTimings(t)">
                  <span v-if="t.llmMs != null">LLM: {{ t.llmMs }} ms</span>
                  <span v-if="t.ttsGenMs != null" class="sep">· 合成: {{ t.ttsGenMs }} ms</span>
                  <span v-if="t.e2eMs != null" class="sep">· 端到端: {{ t.e2eMs }} ms</span>
                </div>
              </div>
            </template>
          </template>
        </div>
      </div>

      <div class="composer">
        <div class="row-mic" v-show="connected">
          <button type="button" @click="toggleMic" class="btn-mic">{{ micOn ? "停止麦克风" : "开始麦克风" }}</button>
          <span class="muted">16kHz PCM 上行，VAD 分句；点「停止」时发送 <code>flush</code>。</span>
        </div>
        <div class="row-text" v-show="connected">
          <textarea v-model="draft" rows="2" placeholder="输入文字后发送；Enter 发送，Shift+Enter 换行" @keydown="onDraftKey" class="ta" :disabled="!connected"></textarea>
          <button type="button" class="btn-send" :disabled="!canSend" @click="sendText">发送</button>
        </div>
      </div>
    </div>
  </div>
  <style>
    .sub { color: #6e6e73; font-size: 14px; max-width: 48rem; line-height: 1.5; }
    .online-debug { max-width: 48rem; }
    .toolbar { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; margin-bottom: 8px; }
    .t-label { font-size: 13px; color: #6e6e73; }
    .t-ws { flex: 1; min-width: 200px; padding: 8px 10px; border: 1px solid #c7c7cc; border-radius: 6px; }
    .t-status { font-size: 14px; }
    .t-status.ok { color: #1a7f37; }
    .t-status.bad { color: #b42318; }
    .warn { color: #b44; font-size: 13px; }
    .layout-chat { display: flex; flex-direction: column; gap: 0; }
    .chat-panel {
      border: 1px solid #d2d2d7;
      border-radius: 10px;
      background: #e8e8ed;
      min-height: 220px;
      max-height: min(56vh, 520px);
      overflow-y: auto;
      padding: 12px 14px;
    }
    .empty { text-align: center; color: #6e6e73; font-size: 14px; margin: 2rem 0; }
    .turn { margin-bottom: 12px; }
    .turn:last-child { margin-bottom: 0; }
    .bubble { border-radius: 12px; padding: 10px 12px; max-width: 92%; font-size: 14px; }
    .bubble .src { font-size: 11px; text-transform: uppercase; letter-spacing: 0.04em; color: #6e6e73; margin-bottom: 4px; }
    .bubble .txt { white-space: pre-wrap; word-break: break-word; line-height: 1.45; }
    .bubble .ts { font-size: 12px; color: #6e6e73; margin-top: 6px; }
    .sep { margin-left: 0.2em; }
    .mono { font-family: ui-monospace, monospace; font-size: 12px; }
    .bubble-user { background: #d1e7ff; margin-left: 12%; }
    .bubble-assistant { background: #fff; border: 1px solid #d2d2d7; }
    .bubble-sys { background: #fff3cd; border: 1px solid #e6d89c; color: #665; font-size: 13px; }
    .actions-row { margin-top: 8px; display: flex; align-items: center; flex-wrap: wrap; gap: 6px; }
    .actions-row .lbl { color: #6e6e73; font-size: 12px; margin-right: 2px; }
    .action-chip {
      display: inline-block;
      padding: 2px 8px;
      border-radius: 999px;
      background: #e9f4ff;
      border: 1px solid #b8dafe;
      color: #0a4d8c;
      font-family: ui-monospace, monospace;
      font-size: 12px;
    }
    .err-line { color: #b42318; font-size: 13px; margin-top: 6px; }
    .row-audio { margin-top: 8px; display: flex; align-items: center; flex-wrap: wrap; gap: 8px; }
    .row-audio .lbl { color: #6e6e73; font-size: 13px; }
    .audio-ctrl { min-width: 200px; height: 32px; }
    .btn-file { padding: 5px 10px; border-radius: 6px; border: 1px solid #c7c7cc; color: #1d1d1f; text-decoration: none; font-size: 12px; background: #fff; }
    .btn-file:hover { background: #f5f5f7; }
    .composer { margin-top: 12px; }
    .row-mic { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; margin-bottom: 8px; }
    .row-text { display: flex; gap: 8px; align-items: flex-end; }
    .ta { flex: 1; padding: 8px 10px; border: 1px solid #c7c7cc; border-radius: 6px; resize: vertical; min-height: 52px; }
    .btn-send, .btn-mic { padding: 8px 16px; border-radius: 6px; border: 1px solid #c7c7cc; background: #fff; cursor: pointer; }
    .btn-send { flex-shrink: 0; }
    .btn-send:disabled { opacity: 0.5; cursor: not-allowed; }
    .btn-mic:hover, .btn-send:hover:not(:disabled) { background: #f5f5f7; }
    .muted { color: #6e6e73; font-size: 12px; }
  </style>
  <script>
    if (!window.Vue) {
      const mount = document.getElementById("app");
      if (mount) {
        mount.innerHTML = '<div class="bubble bubble-sys">前端依赖 Vue 加载失败，请检查服务器到 CDN 的网络连通性。</div>';
      }
    } else {
    const { createApp } = Vue;
    const FRAME_SAMPLES = 480;

    function resampleF32(f32, inRate, outRate) {
      if (Math.abs(inRate - outRate) < 1) return f32;
      const outLen = Math.floor(f32.length * (outRate / inRate));
      const out = new Float32Array(outLen);
      const r = inRate / outRate;
      for (let i = 0; i < outLen; i++) {
        const x = i * r;
        const j = Math.floor(x);
        const f = x - j;
        out[i] = j + 1 < f32.length ? (1 - f) * f32[j] + f * f32[j + 1] : f32[j];
      }
      return out;
    }
    function floatToI16(f32) {
      const n = f32.length;
      const a = new Int16Array(n);
      for (let i = 0; i < n; i++) {
        const v = Math.round(f32[i] * 32768);
        a[i] = v < -32768 ? -32768 : v > 32767 ? 32767 : v;
      }
      return a;
    }
    function u8ToB64(u8) {
      let s = "";
      for (let i = 0; i < u8.length; i++) s += String.fromCharCode(u8[i]);
      return btoa(s);
    }
    function mergeI16(a, b) {
      const m = new Int16Array(a.length + b.length);
      m.set(a);
      m.set(b, a.length);
      return m;
    }
    function getUserMediaCompat(constraints) {
      if (navigator.mediaDevices && navigator.mediaDevices.getUserMedia) {
        return navigator.mediaDevices.getUserMedia(constraints);
      }
      const legacy =
        navigator.getUserMedia ||
        navigator.webkitGetUserMedia ||
        navigator.mozGetUserMedia ||
        navigator.msGetUserMedia;
      if (!legacy) {
        return Promise.reject(new Error("当前浏览器不支持 getUserMedia"));
      }
      return new Promise((resolve, reject) => legacy.call(navigator, constraints, resolve, reject));
    }
    function i16ToWavBlob(i16, sampleRate = 16000) {
      const pcmBytes = i16.length * 2;
      const ab = new ArrayBuffer(44 + pcmBytes);
      const dv = new DataView(ab);
      let off = 0;
      function ws(s) { for (let i = 0; i < s.length; i++) dv.setUint8(off++, s.charCodeAt(i)); }
      function u16(v) { dv.setUint16(off, v, true); off += 2; }
      function u32(v) { dv.setUint32(off, v, true); off += 4; }
      ws("RIFF"); u32(36 + pcmBytes); ws("WAVE");
      ws("fmt "); u32(16); u16(1); u16(1);
      u32(sampleRate); u32(sampleRate * 2); u16(2); u16(16);
      ws("data"); u32(pcmBytes);
      for (let i = 0; i < i16.length; i++) {
        dv.setInt16(off, i16[i], true);
        off += 2;
      }
      return new Blob([ab], { type: "audio/wav" });
    }

    createApp({
      data() {
        return {
          nextId: 0,
          wsUrl: window.__DESKBOT_WS_DEFAULT__ || "ws://127.0.0.1:9000",
          ws: null,
          connected: false,
          statusText: "未连接",
          draft: "",
          turns: [],
          activeTurn: null,
          _tAsr0: null,
          _tAsrText: null,
          _tLlm: null,
          micOn: false,
          _ctx: null,
          _source: null,
          _proc: null,
          _mute: null,
          _stream: null,
          _i16Buffer: new Int16Array(0),
          _captureI16: new Int16Array(0),
          _pendingTtsTurn: null,
        };
      },
      computed: {
        canSend() {
          if (!this.connected) return false;
          return !!this.draft.trim();
        },
      },
      watch: { turns: { deep: true, handler() { this._scrollEnd(); } } },
      methods: {
        hasTimings(t) { return t.llmMs != null || t.ttsGenMs != null || t.e2eMs != null; },
        _scrollEnd() {
          this.$nextTick(() => {
            const el = this.$refs.chatBox;
            if (el) el.scrollTop = el.scrollHeight;
          });
        },
        ms(t0, t1) {
          if (t0 == null || t1 == null) return null;
          return Math.round((t1 - t0) * 1000);
        },
        beginTurn() {
          const t = { id: ++this.nextId, userText: "… 识别中", userSource: "asr" };
          if (this._captureI16.length > 0) {
            const blob = i16ToWavBlob(this._captureI16, 16000);
            t.userAudioUrl = URL.createObjectURL(blob);
            t.userAudioName = `user-${t.id}.wav`;
            this._captureI16 = new Int16Array(0);
          }
          this.activeTurn = t;
          this._pendingTtsTurn = null;
          this.turns.push(t);
        },
        onJson(d) {
          const tmono = d.t_mono;
          if (d.type === "pb_start") {
            if (this.activeTurn && tmono != null) {
              const t0 = this._tAsrText != null ? this._tAsrText : this._tAsr0;
              if (t0 != null) this.activeTurn.llmMs = this.ms(t0, tmono);
              this._tLlm = tmono;
              this._pendingTtsTurn = this.activeTurn;
            }
            return;
          }
          if (d.type === "pb_single" && this.activeTurn && this.activeTurn.llmMs == null && tmono != null) {
            const t0 = this._tAsrText != null ? this._tAsrText : this._tAsr0;
            if (t0 != null) this.activeTurn.llmMs = this.ms(t0, tmono);
            this._tLlm = tmono;
            this._pendingTtsTurn = this.activeTurn;
          }
          if ((d.type === "pb_end" || d.type === "pb_single") && d.t_mono != null && this._tAsr0 != null) {
            if (this.activeTurn) {
              this.activeTurn.e2eMs = this.ms(this._tAsr0, d.t_mono);
              this.activeTurn = null;
            }
            return;
          }
        },
        attachTts(u8) {
          const target = this.activeTurn || this._pendingTtsTurn;
          if (!target) return;
          if (target.audioUrl) {
            try { URL.revokeObjectURL(target.audioUrl); } catch (e) {}
            target.audioUrl = null;
          }
          target.audioUrl = URL.createObjectURL(
            new Blob([u8], { type: "audio/wav" })
          );
          target.audioName = `assistant-${target.id}.wav`;
          if (this._pendingTtsTurn && this._pendingTtsTurn.id === target.id) {
            this._pendingTtsTurn = null;
          }
        },
        onWsMessage(ev) {
          if (ev.data instanceof Blob) {
            ev.data.arrayBuffer().then((ab) => this.attachTts(new Uint8Array(ab)));
            return;
          }
          if (ev.data instanceof ArrayBuffer) {
            this.attachTts(new Uint8Array(ev.data));
            return;
          }
          let d;
          try { d = JSON.parse(ev.data); } catch (e) { return; }
          this.onJson(d);
        },
        async stopMic() {
          this.micOn = false;
          if (this._proc) {
            this._proc.disconnect();
            this._proc.onaudioprocess = null;
            this._proc = null;
          }
          if (this._mute) { this._mute.disconnect(); this._mute = null; }
          if (this._source) { this._source.disconnect(); this._source = null; }
          if (this._stream) { this._stream.getTracks().forEach((x) => x.stop()); this._stream = null; }
          this._i16Buffer = new Int16Array(0);
        },
        async startMic() {
          if (!this.ws || this.ws.readyState !== 1) return;
          if (!window.isSecureContext && location.hostname !== "localhost" && location.hostname !== "127.0.0.1") {
            this.turns.push({
              id: ++this.nextId,
              errNotice: "浏览器安全限制：请使用 HTTPS 或 localhost 打开页面后再启用麦克风。",
            });
            return;
          }
          this._ctx = this._ctx || new (window.AudioContext || window.webkitAudioContext)();
          const c = this._ctx;
          if (c.state === "suspended") await c.resume();
          const inRate = c.sampleRate;
          try {
            this._stream = await getUserMediaCompat({
              audio: { channelCount: 1, echoCancellation: true, noiseSuppression: true },
            });
          } catch (e) {
            this.turns.push({
              id: ++this.nextId,
              errNotice: `麦克风启动失败: ${e?.message || e}`,
            });
            return;
          }
          this._source = c.createMediaStreamSource(this._stream);
          this._proc = c.createScriptProcessor(4096, 1, 1);
          this._proc.onaudioprocess = (e) => {
            if (!this.micOn || !this.ws || this.ws.readyState !== 1) return;
            const f32 = e.inputBuffer.getChannelData(0);
            const f16 = resampleF32(f32, inRate, 16000);
            const i16 = floatToI16(f16);
            this._i16Buffer = mergeI16(this._i16Buffer, i16);
            while (this._i16Buffer.length >= FRAME_SAMPLES) {
              const chunk = this._i16Buffer.subarray(0, FRAME_SAMPLES);
              this._i16Buffer = this._i16Buffer.subarray(FRAME_SAMPLES);
              this._captureI16 = mergeI16(this._captureI16, chunk);
              const u8 = new Uint8Array(chunk.buffer, chunk.byteOffset, FRAME_SAMPLES * 2);
              this.ws.send(JSON.stringify({ type: "audio", codec: "pcm16", data: u8ToB64(u8) }));
            }
          };
          this._mute = c.createGain();
          this._mute.gain.value = 0;
          this._source.connect(this._proc);
          this._proc.connect(this._mute);
          this._mute.connect(c.destination);
          this.micOn = true;
        },
        async toggleMic() {
          if (this.micOn) {
            if (this.ws && this.ws.readyState === 1) {
              this._tAsr0 = performance.now() / 1000;
              this._tAsrText = this._tLlm = null;
              this.beginTurn();
              this.ws.send(JSON.stringify({ type: "flush" }));
            }
            await this.stopMic();
          } else {
            await this.startMic();
          }
        },
        onDraftKey(e) {
          if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); this.sendText(); }
        },
        sendText() {
          const text = (this.draft || "").trim();
          if (!text || !this.ws || this.ws.readyState !== 1) return;
          this._tAsr0 = performance.now() / 1000;
          this._tAsrText = this._tLlm = null;
          const t = { id: ++this.nextId, userText: text, userSource: "text" };
          this.activeTurn = t;
          this._pendingTtsTurn = null;
          this.turns.push(t);
          this.ws.send(JSON.stringify({ type: "user_text", text }));
          this.draft = "";
        },
        connectWs() {
          return new Promise((resolve) => {
            this.ws = new WebSocket(this.wsUrl);
            this.ws.binaryType = "blob";
            this.ws.onopen = () => { this.connected = true; this.statusText = "已连接"; resolve(); };
            this.ws.onerror = () => { this.statusText = "错误"; };
            this.ws.onclose = () => {
              this.connected = false;
              this.statusText = "已断开";
              this.stopMic();
            };
            this.ws.onmessage = (ev) => this.onWsMessage(ev);
          });
        },
        async toggleConn() {
          if (this.connected && this.ws) {
            this.ws.close();
            this.ws = null;
            return;
          }
          this.statusText = "连接中…";
          try { await this.connectWs(); } catch (e) {
            this.statusText = "连接失败";
            this.connected = false;
          }
        },
      },
      beforeUnmount() {
        this.stopMic();
        for (const t of this.turns) {
          if (t.audioUrl) { try { URL.revokeObjectURL(t.audioUrl); } catch (e) {} }
          if (t.userAudioUrl) { try { URL.revokeObjectURL(t.userAudioUrl); } catch (e) {} }
        }
      },
    }).mount("#app");
    }
  </script>
  {% endraw %}
{% endblock %}

debug_simulation.html:
{% extends "base.html" %}
{% block page_title %}仿真调试 · Deskbot Server{% endblock %}
{% block extra_head %}
  <script>
    window.__SIM__ = {
      defaultSpk: {{ default_spk|int }},
      sampleRate: {{ sample_rate|int }},
      faceLcdW: {{ face_lcd_w|int }},
      faceLcdH: {{ face_lcd_h|int }},
      defaultFaceCircles: {{ default_face_circles|tojson }},
    };
  </script>
  <script src="{{ url_for('static', filename='vendor/vue.global.prod.min.js') }}"></script>
{% endblock %}
{% block content %}
  <h1>仿真调试</h1>
  <p class="sub">
    左侧：调用豆包 TTS + 音素分片，生成 <code>pb_*</code> 协议预览并与口型表合成表情序列；播放时整段音频与口型时间轴对齐。
    右侧：在 **284×240** 彩色 LCD 逻辑画布上编辑；**鼻与双眼默认为圆**；**音素→嘴型表**预置约两百余个中文音素，嘴型均为**矩形**（静音扁、韵母+声调略张大、声母中等）；可「重置」恢复；数据可存 localStorage。
    协议字段约定见仓库 <code>docs/esp32_pb_protocol.md</code>。
  </p>
  {% raw %}
  <div id="app" class="sim-root">
    <div class="sim-split">
      <section class="sim-left card">
        <h2 class="h2">调试</h2>
        <textarea v-model="draft" rows="3" class="ta" placeholder="输入要合成的文字"></textarea>
        <div class="row2">
          <label class="lbl">spk_id</label>
          <input v-model.number="spkId" type="number" min="0" class="num" />
          <button type="button" class="btn" :disabled="busy" @click="fetchTts">{{ busy ? "请求中…" : "合成（音素+音频）" }}</button>
        </div>
        <p v-if="errL" class="err">{{ errL }}</p>
        <details v-if="tts" class="box" open>
          <summary>TTS 返回摘要</summary>
          <p class="mono sm">sample_rate={{ tts.sample_rate }} · pcm_total={{ tts.pcm_total_bytes }} · segments={{ tts.segments.length }}</p>
          <div class="tbl-wrap">
            <table class="tbl">
              <thead><tr><th>#</th><th>phoneme</th><th>id</th><th>ms</th><th>pcm_bytes</th></tr></thead>
              <tbody>
                <tr v-for="(s,i) in tts.segments" :key="i">
                  <td>{{ i+1 }}</td><td class="mono">{{ s.phoneme }}</td><td>{{ s.phoneme_id }}</td><td>{{ s.ms }}</td><td>{{ s.pcm_bytes }}</td>
                </tr>
              </tbody>
            </table>
          </div>
        </details>
        <div class="row2">
          <button type="button" class="btn secondary" :disabled="!tts" @click="buildAnimAndProtocol">生成表情序列 + 协议预览</button>
        </div>
        <details v-if="animSeq.length" class="box">
          <summary>表情序列（phonemeSeqToAnimSeq）</summary>
          <pre class="pre">{{ animSeqJson }}</pre>
        </details>
        <details v-if="pbPreview.length" class="box">
          <summary>pb 协议 JSON（不含 binary 本体）</summary>
          <pre class="pre">{{ pbPreviewJson }}</pre>
        </details>
        <div class="row2">
          <button type="button" class="btn primary" :disabled="!tts || !animSeq.length || playing" @click="playSim">播放（声画同步）</button>
          <button type="button" class="btn secondary" :disabled="!playing" @click="stopSim">停止</button>
        </div>
        <div class="preview-wrap">
          <span class="lbl">口型预览（当前帧，284×240）</span>
          <div class="canvas-wrap canvas-wrap--sm">
            <canvas ref="pvCanvas" class="pv-canvas" width="284" height="240"></canvas>
          </div>
        </div>
      </section>

      <section class="sim-right card sim-right--wide">
        <h2 class="h2">表情设计</h2>
        <p class="hint">画布逻辑分辨率 <strong>284×240</strong>（与设备彩色 LCD 一致）；下为放大显示。新图形画在「当前图层」。</p>
        <div class="row2 layer-row">
          <label class="lbl">当前图层</label>
          <select v-model="activeLayer" class="sel">
            <option v-for="o in layerOptions" :key="o.id" :value="o.id">{{ o.label }}</option>
          </select>
        </div>
        <div class="tools">
          <button type="button" :class="['tbtn', tool==='pointer'?'on':'']" @click="tool='pointer'" title="选择与移动">指针</button>
          <button type="button" :class="['tbtn', tool==='circle'?'on':'']" @click="tool='circle'">圆</button>
          <button type="button" :class="['tbtn', tool==='rect'?'on':'']" @click="tool='rect'">矩形</button>
          <button type="button" :class="['tbtn', tool==='line'?'on':'']" @click="tool='line'">线段</button>
          <button type="button" class="tbtn danger" @click="clearCanvas">清空画布</button>
        </div>
        <div class="canvas-wrap" ref="canvasWrap">
          <canvas
            ref="editCanvas"
            class="edit-canvas"
            :class="canvasCursorClass"
            width="284"
            height="240"
            @mousedown="onCanvasDown"
            @mousemove="onCanvasMove"
            @mouseup="onCanvasUp"
            @mouseleave="onCanvasUp"
          ></canvas>
        </div>
        <div class="tool-params card-inset">
          <div class="tp-title">工具 / 参数</div>
          <div v-if="tool==='pointer'" class="tp-body mono sm">
            <template v-if="selectedRef">
              已选：<strong>{{ selectedRef.layer }}</strong> #{{ selectedRef.index }} ·
              <span v-if="selectedShapeDesc">{{ selectedShapeDesc }}</span>
            </template>
            <template v-else>点击图形可选中；拖曳移动。未选中。</template>
          </div>
          <div v-else-if="tool==='circle'" class="tp-body mono sm">
            <span v-if="drag">绘制中：圆心 ({{ drag.x0 }}, {{ drag.y0 }}) 半径 ≈ {{ circleDraftR }}</span>
            <span v-else>拖曳确定半径；单击用默认半径 8。</span>
          </div>
          <div v-else-if="tool==='rect'" class="tp-body mono sm">
            <span v-if="drag">矩形：左上角 ({{ rectDraft.x }}, {{ rectDraft.y }}) 宽 {{ rectDraft.w }} 高 {{ rectDraft.h }}</span>
            <span v-else>拖曳确定矩形。</span>
          </div>
          <div v-else-if="tool==='line'" class="tp-body mono sm">
            <span v-if="drag">线段：({{ drag.x0 }}, {{ drag.y0 }}) → ({{ drag.x1 }}, {{ drag.y1 }})</span>
            <span v-else>拖曳确定两端点。</span>
          </div>
        </div>
        <div class="row2">
          <button type="button" class="btn secondary" @click="saveRegionTemplate">保存全部图层到 localStorage</button>
        </div>

        <h3 class="h3">音素 → 嘴型 <span class="muted sm">（共 {{ mouthMapRows.length }} 行）</span></h3>
        <p class="hint">从合成结果一键导入音素行；「应用嘴画布」把当前画布上 <strong>嘴 mouth</strong> 图层图形写入该音素的 JSON。</p>
        <div class="row2">
          <button type="button" class="btn secondary" :disabled="!tts" @click="importPhonemesFromTts">从上次合成导入行</button>
          <button type="button" class="btn secondary" @click="addMapRow">空行</button>
          <button type="button" class="btn secondary" @click="resetMouthMapDefaults">重置音素嘴型表（矩形默认）</button>
          <button type="button" class="btn secondary" @click="resetFaceDefaults">重置眼鼻圆</button>
          <button type="button" class="btn secondary" @click="saveMap">保存映射到 localStorage</button>
          <button type="button" class="btn secondary" @click="loadMap">重新加载</button>
        </div>
        <div class="tbl-wrap map-tbl">
          <table class="tbl tbl-map">
            <thead>
              <tr>
                <th class="col-idx">序号</th>
                <th class="col-ph">音素</th>
                <th class="col-json">嘴型（JSON）</th>
