              </tr>
            </thead>
            <tbody>
              <tr v-for="(row,i) in mouthMapRows" :key="i">
                <td class="col-idx mono">{{ i + 1 }}</td>
                <td class="col-ph"><input v-model="row.phoneme" class="inp sm mono" /></td>
                <td class="col-json"><textarea v-model="row.mouthJson" rows="5" class="ta sm mono ta-json"></textarea></td>
                <td class="col-act"><button type="button" class="btn sm" @click="applyMouthFromEditor(row)">应用嘴画布</button></td>
              </tr>
            </tbody>
          </table>
        </div>
      </section>
    </div>
  </div>
