{% block extra_js %}
<script>
    const initial = window.__DOUBAO_TTS__ || {};
    const speakers = window.__DOUBAO_TTS_SPEAKERS__ || [];
    const TTS_DEBUG_HISTORY_LS_KEY = "deskbot_tts_debug_history";
    const TTS_DEBUG_HISTORY_MAX = 20;
    const { createApp } = Vue;
    createApp({
      delimiters: ['[[', ']]'],
      data() {
        return {
          cfg: { api_key_set: false, ...initial },
          speakers,
          speakerPreset: "",
          speakerFilter: "",
          draft: "你好，这是豆包语音合成调试。",
          savingCfg: false,
          saveMsg: "",
          cfgErr: "",
          pending: false,
          err: "",
          result: null,
          audioUrl: "",
          history: [],
          selectedHistoryId: "",
        };
      },
      computed: {
        filteredSpeakers() {
          const q = (this.speakerFilter || "").trim().toLowerCase();
          if (!q) return this.speakers;
          return this.speakers.filter((item) => {
            const hay = [item.label, item.id, item.scene, item.description].join(" ").toLowerCase();
            return hay.includes(q);
          });
        },
        jsonPretty() {
          if (!this.result) return "";
          const { wav_base64, ...rest } = this.result;
          return JSON.stringify(rest, null, 2);
        },
        speakerHint() {
          const current = (this.cfg.speaker || "").trim();
          if (!current) return "可从上方预设选择，或在下方直接填写 speaker ID。";
          const preset = this.speakers.find((item) => item.id === current);
          if (!preset) return "当前为自定义 speaker。";
          const parts = [preset.scene, preset.description].filter(Boolean);
          const resource = preset.resource_id ? "建议 Resource ID: " + preset.resource_id : "";
          return [parts.join(" · "), resource].filter(Boolean).join(" · ");
        },
      },
      mounted() {
        this.syncSpeakerPreset();
        this.loadHistory();
      },
      methods: {
        applySpeakerPreset() {
          const preset = this.speakers.find((item) => item.id === this.speakerPreset);
          if (!preset) return;
          this.cfg.speaker = preset.id;
          if (preset.resource_id) {
            this.cfg.resource_id = preset.resource_id;
          }
        },
        syncSpeakerPreset() {
          const current = (this.cfg.speaker || "").trim();
          const matched = this.speakers.find((item) => item.id === current);
          this.speakerPreset = matched ? matched.id : "";
        },
        revokeAudio() {
          if (this.audioUrl && this.audioUrl.startsWith("blob:")) {
            URL.revokeObjectURL(this.audioUrl);
          }
          this.audioUrl = "";
        },
        loadHistory() {
          try {
            const raw = localStorage.getItem(TTS_DEBUG_HISTORY_LS_KEY);
            if (!raw) return;
            const arr = JSON.parse(raw);
            if (!Array.isArray(arr)) return;
            this.history = arr
              .filter((r) => r && typeof r.text === "string")
              .slice(0, TTS_DEBUG_HISTORY_MAX)
              .map((r) => ({
                id: String(r.id || (Date.now() + Math.random())),
                text: r.text,
                createdAt: r.createdAt || "—",
                status: r.status === "error" ? "error" : "ok",
                error: r.error || "",
                elapsed_ms: r.elapsed_ms ?? null,
                pcm_total_bytes: r.pcm_total_bytes ?? null,
                sample_rate: r.sample_rate ?? null,
                speaker: r.speaker || "",
                events: r.events || null,
                wav_base64: r.wav_base64 || "",
              }));
          } catch (e) { /* ignore */ }
        },
        persistHistory() {
          const trim = (n) => {
            const slice = this.history.slice(0, n);
            try {
              localStorage.setItem(TTS_DEBUG_HISTORY_LS_KEY, JSON.stringify(slice));
              if (slice.length < this.history.length) {
                this.history.length = slice.length;
              }
              return true;
            } catch (e) {
              return false;
            }
          };
          if (trim(TTS_DEBUG_HISTORY_MAX)) return;
          for (let n = Math.floor(TTS_DEBUG_HISTORY_MAX / 2); n >= 1; n -= 1) {
            if (trim(n)) return;
          }
        },
        pushHistoryEntry(entry) {
          this.history.unshift(entry);
          if (this.history.length > TTS_DEBUG_HISTORY_MAX) {
            this.history.length = TTS_DEBUG_HISTORY_MAX;
          }
          this.persistHistory();
        },
        clearHistory() {
          if (!this.history.length) return;
          if (!window.confirm("确定清空全部 TTS 历史记录？")) return;
          this.history = [];
          this.selectedHistoryId = "";
          try {
            localStorage.removeItem(TTS_DEBUG_HISTORY_LS_KEY);
          } catch (e) { /* ignore */ }
        },
        audioUrlFromBase64(wavBase64) {
          const bin = Uint8Array.from(atob(wavBase64), (c) => c.charCodeAt(0));
          const blob = new Blob([bin], { type: "audio/wav" });
          return URL.createObjectURL(blob);
        },
        replayHistory(row) {
          if (!row) return;
          this.selectedHistoryId = row.id;
          this.draft = row.text;
          if (row.status !== "ok" || !row.wav_base64) {
            this.revokeAudio();
            this.result = null;
            this.err = row.error || "该条目无缓存音频，请重新合成";
            return;
          }
          this.err = "";
          this.revokeAudio();
          this.result = {
            elapsed_ms: row.elapsed_ms,
            pcm_total_bytes: row.pcm_total_bytes,
            sample_rate: row.sample_rate,
            events: row.events,
          };
          this.audioUrl = this.audioUrlFromBase64(row.wav_base64);
        },
        async saveConfig() {
          this.cfgErr = "";
          this.saveMsg = "";
          this.savingCfg = true;
          try {
            const res = await fetch("/api/doubao_tts/config", {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify(this.cfg),
            });
            const data = await res.json();
            if (!data.ok) {
              this.cfgErr = data.error || ("HTTP " + res.status);
              return;
            }
            this.cfg = { ...data.config, api_key: "" };
            if (data.config && data.config.api_key_set) {
              this.cfg.api_key_set = true;
            }
            this.saveMsg = "已保存到 .env";
          } catch (e) {
            this.cfgErr = String(e && e.message ? e.message : e);
          } finally {
            this.savingCfg = false;
          }
        },
        async run() {
          this.err = "";
          this.revokeAudio();
          this.result = null;
          this.pending = true;
          try {
            const res = await fetch("/api/doubao_tts/synthesize", {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({ text: this.draft.trim(), ...this.cfg }),
            });
            const data = await res.json();
            if (!data.ok) {
              this.err = (data.error || ("HTTP " + res.status))
                + (data.elapsed_ms != null ? " (" + data.elapsed_ms + " ms)" : "");
              this.pushHistoryEntry({
                id: `${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
                text: this.draft.trim(),
                createdAt: new Date().toLocaleString(),
                status: "error",
                error: this.err,
                elapsed_ms: data.elapsed_ms ?? null,
                pcm_total_bytes: null,
                sample_rate: null,
                speaker: (this.cfg.speaker || "").trim(),
                events: null,
                wav_base64: "",
              });
              return;
            }
            this.result = data;
            this.audioUrl = this.audioUrlFromBase64(data.wav_base64);
            const entryId = `${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
            this.selectedHistoryId = entryId;
            const { wav_base64, ...meta } = data;
            this.pushHistoryEntry({
              id: entryId,
              text: this.draft.trim(),
              createdAt: new Date().toLocaleString(),
              status: "ok",
              error: "",
              elapsed_ms: meta.elapsed_ms ?? null,
              pcm_total_bytes: meta.pcm_total_bytes ?? null,
              sample_rate: meta.sample_rate ?? null,
              speaker: (this.cfg.speaker || "").trim(),
              events: meta.events ?? null,
              wav_base64: wav_base64 || "",
            });
          } catch (e) {
            this.err = String(e && e.message ? e.message : e);
            this.pushHistoryEntry({
              id: `${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
              text: this.draft.trim(),
              createdAt: new Date().toLocaleString(),
              status: "error",
              error: this.err,
              elapsed_ms: null,
              pcm_total_bytes: null,
              sample_rate: null,
              speaker: (this.cfg.speaker || "").trim(),
              events: null,
              wav_base64: "",
            });
          } finally {
            this.pending = false;
          }
        },
      },
      beforeUnmount() {
        this.revokeAudio();
      },
    }).mount("#app");
  </script>
{% endblock %}

