.qt-field .row{display:flex;gap:8px}
.qt-field .row>*{flex:1}
.qt-readonly{font-size:11px;color:var(--faint);font-family:var(--mono);word-break:break-all}
.qt-ref-row{display:flex;gap:6px;align-items:center;margin-bottom:4px}
.qt-ref-row span{flex:1;font-family:var(--mono);font-size:11px;color:var(--ink);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.qt-ref-row button{background:none;border:none;color:#ff6b6b;cursor:pointer;font-size:13px;padding:2px 4px}
.qt-ref-row .add-btn{color:#4ade80}
.qt-btn-row{display:flex;gap:6px;flex-wrap:wrap;margin-top:12px}
.qt-btn-row .btn{flex:1;text-align:center;padding:5px 8px;font-size:12px}
.qt-sim-out{margin-top:8px;padding:6px 8px;font:10px/1.5 "Space Mono",monospace;color:#7dd3fc;background:rgba(18,36,58,.5);border:1px solid rgba(125,211,252,.25);border-radius:6px;white-space:pre-wrap;word-break:break-all;max-height:90px;overflow:auto}
.qt-empty{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;color:var(--faint);font-size:13px}
.qt-modal{position:fixed;inset:0;background:rgba(0,0,0,.6);display:flex;align-items:center;justify-content:center;z-index:100}
.qt-modal-box{background:var(--panel);border:var(--bw) solid var(--line);border-radius:var(--rl);box-shadow:var(--shadow);width:min(620px,92vw);padding:16px}
.qt-modal-box textarea{width:100%;height:300px;box-sizing:border-box;font:11px/1.5 "Space Mono",monospace;color:var(--ink);background:var(--panel2);border:1px solid var(--line);border-radius:8px;padding:8px;resize:vertical}
.qt-badge{display:inline-block;padding:1px 6px;border-radius:999px;font-size:10px;font-family:var(--mono);white-space:nowrap}
.qt-badge.not_started{background:#1f232d;color:#8a8a94}
.qt-badge.running{background:#12243a;color:#7dd3fc}
.qt-badge.completed{background:#0f2b1c;color:#4ade80}
</style>
{% endblock %}

{% block content %}
<div id="questApp" v-cloak>
  <div class="qt-top">
    <span class="qt-menu-label">载入</span>
    <select v-model="pbName" @change="onPbSwitch">
      <option v-for="p in playbooks" :key="p" :value="p">[[ p ]]</option>
    </select>
    <button class="btn" @click="openNewModal">新建</button>
    <button class="btn" @click="savePb" :disabled="!pb">保存</button>
    <button class="btn ghost" @click="importClick" :disabled="!pb">导入</button>
    <button class="btn ghost" @click="exportPb" :disabled="!pb">导出</button>
    <div class="qt-palette" :class="{dragging: paletteDragging}" draggable="true"
         title="拖到画布上创建任务" @dragstart="onPaletteDragStart" @dragend="onPaletteDragEnd">
      ＋新任务
    </div>
    <span class="qt-saved" :class="{on: savedOn}">已保存</span>
    <span class="qt-top-err" v-if="topErr">[[ topErr ]]</span>
    <span class="qt-hint">右键画布/拖「＋新任务」添加任务 · 拖节点头部移动 · 连线：按住橙色「后继口」拖到目标任务松开，或点一下后继口再点目标任务（点空白/Esc 取消）· 点连线删除 · 节点主体直接编辑任务描述 · 底部中点把手可上下拉伸高度</span>
  </div>
  <input ref="fileInput" type="file" accept=".json,application/json" style="display:none" @change="onFileImport"/>

  <div class="qt-main">
    <div class="qt-canvas" ref="canvas" :class="{dragging: pan, linking: !!linkArm}"
         @contextmenu.prevent="onCanvasContext"
         @dragover.prevent
         @drop.prevent="onCanvasDrop"
         @wheel="onWheel"
         @mousedown.prevent="onCanvasDown">
      <div class="qt-world" ref="world" :style="{width: canvasSize.w*zoom+'px', height: canvasSize.h*zoom+'px'}">
        <div class="qt-world-inner" ref="worldInner" :style="worldStyle">
          <svg class="qt-edges" :width="canvasSize.w" :height="canvasSize.h">
            <defs>
              <marker id="qt-arrow" viewBox="0 0 10 10" refX="8.5" refY="5" markerWidth="7"
                      markerHeight="7" orient="auto-start-reverse">
                <path d="M0,0 L10,5 L0,10 z" fill="#7dd3fc"/>
              </marker>
            </defs>
            <g v-for="(e,i) in edges" :key="'e'+i">
              <path :d="edgePath(e)" fill="none" :stroke="edgeColor" stroke-width="2"
                    marker-end="url(#qt-arrow)" @click.stop="removeEdge($event, e)"/>
            </g>
            <line v-if="linkDrag" :x1="linkDrag.x1" :y1="linkDrag.y1" :x2="linkDrag.x2" :y2="linkDrag.y2"
                  stroke="#ff5a00" stroke-width="2" stroke-dasharray="6 4"/>
          </svg>

          <div v-if="!playbooks.length" class="qt-empty">还没有剧本 —— 点「＋新建剧本」开始</div>
          <div v-else-if="!tasks.length" class="qt-empty">这个剧本还没有任务 —— 把左上角「＋新任务」图标拖到画布上创建</div>
          <div v-for="(t,i) in tasks" :key="i" class="qt-node" :data-id="t.id"
               :class="{sel: selectedId===t.id}"
               :style="nodeStyle(t)" @mousedown.prevent="onNodeDown($event, t)"
               @click="onNodeClick(t)">
            <div class="qt-node-head">
              <span class="qt-head-idtitle">
                <template v-if="!isEditing(t, 'id')">
                  <span class="qt-label qt-label-id" title="双击编辑 id（改后自动更新后继引用）"
                        @dblclick="startEdit(t, 'id')">[[ t.id ]]</span>
                </template>
                <input v-else class="qt-inline qt-inline-id qt-edit-on" v-model="t.id" title="回车保存，Esc 取消"
                       @keydown.enter="finishEdit(t, 'id')" @keydown.esc="cancelEdit(t, 'id')"
                       @blur="finishEdit(t, 'id')" @mousedown.stop @click.stop>
                <span class="qt-head-colon">:</span>
                <select class="qt-type-select" :class="'qt-type-' + (t.type || 'once')"
                        :value="t.type || 'once'" title="任务类型（一次性/日常/长期）"
                        @mousedown.stop @change="onTypeChange(t, $event)">
                  <option value="once">一次性</option>
                  <option value="daily">日常</option>
                  <option value="long_term">长期</option>
                </select>
              </span>
              <select class="qt-state-select" :class="'st-' + instStatus(t)" :value="instStatus(t)"
                      title="沙箱状态（直接切换）" @change="setState(t, $event.target.value)"
                      @mousedown.stop="selectTask(t)">
                <option value="not_started">未开始</option>
                <option value="running">进行中</option>
                <option value="completed">已完成</option>
              </select>
            </div>
            <div class="qt-prompt-wrap">
              <textarea class="qt-prompt" v-model="t.prompt" placeholder="填写任务描述 prompt…"
                        title="任务描述（AI 据此判断是否推进/完成）"
                        @mousedown.stop @change="saveField(t, 'prompt')"></textarea>
            </div>
            <div class="qt-port qt-port-in" title="输入口：被前置任务激活（连线指向这里）"></div>
            <div class="qt-port qt-port-out" :class="{ 'qt-linking': linkArm === t.id }"
                 :data-id="t.id"
                 title="后继口：①按住拖到目标任务上松开即连线 ②或点一下本口进入连线模式，再点目标任务"
                 @mousedown.stop.prevent="onPortDown($event, t)"></div>
            <div class="qt-resize" title="上下拉伸节点高度" @mousedown.stop.prevent="onResizeDown($event, t)"></div>
          </div>

          <div v-if="ctxMenu" class="qt-ctx" :style="{left: ctxMenu.x+'px', top: ctxMenu.y+'px'}">
            <button @click="ctxAddTask">＋新任务</button>
          </div>
        </div>
      </div>
    </div>
    <div class="qt-zoomctl" style="position:absolute;right:320px;bottom:14px;z-index:40;display:flex;align-items:center;gap:4px;background:var(--panel);border:var(--bw) solid var(--line);border-radius:10px;padding:4px 6px;box-shadow:var(--shadow)">
      <button @click="zoomBy(1/1.25)" title="缩小" style="background:none;border:none;color:var(--dim);font-size:14px;cursor:pointer;padding:0 6px;line-height:1">－</button>
      <span style="font-family:var(--mono);font-size:11px;color:var(--dim);min-width:38px;text-align:center">[[ Math.round(zoom*100) ]]%</span>
      <button @click="zoomBy(1.25)" title="放大" style="background:none;border:none;color:var(--dim);font-size:14px;cursor:pointer;padding:0 6px;line-height:1">＋</button>
      <button @click="resetView" title="复位（100%，回到原点）" style="background:none;border:none;color:var(--dim);font-size:12px;cursor:pointer;padding:0 6px">复位</button>
    </div>

    <aside class="qt-panel" v-if="selected">
      <h3>
        <span class="qt-head-idtitle" style="gap:2px;min-width:0">
          <template v-if="!isEditing(selected, 'id')">
            <span class="qt-label qt-label-id" title="双击编辑 id" @dblclick="startEdit(selected, 'id')">[[ selected.id ]]</span>
          </template>
          <input v-else class="qt-inline qt-inline-id qt-edit-on" v-model="selected.id" title="回车保存，Esc 取消"
                 @keydown.enter="finishEdit(selected, 'id')" @keydown.esc="cancelEdit(selected, 'id')"
                 @blur="finishEdit(selected, 'id')" @mousedown.stop @click.stop>
          <span class="qt-head-colon">:</span>
          <span class="qt-type" :class="'qt-type-' + (selected.type || 'once')">[[ typeText(selected.type) ]]</span>
        </span>
        <select class="qt-state-select" :class="'st-' + instStatus(selected)" :value="instStatus(selected)"
                title="沙箱状态（直接切换）" @change="setState(selected, $event.target.value)">
          <option value="not_started">未开始</option>
          <option value="running">进行中</option>
          <option value="completed">已完成</option>
        </select>
      </h3>
      <div class="qt-field">
        <label>类型（once 一次性 / daily 日常 / long_term 长期）</label>
        <select :value="selected.type || 'once'" @change="selected.type=$event.target.value; saveField(selected, 'type')">
          <option value="once">一次性：完成即收尾，自动激活后继</option>
          <option value="daily">日常：永不结束，每次完成记入该用户当日记录</option>
          <option value="long_term">长期：永不结束，实质进展累计记入该用户档案</option>
        </select>
      </div>
      <div class="qt-field">
        <label>任务描述 prompt（AI 要推进的内容 / 达成判定依据）</label>
        <textarea v-model="selected.prompt" placeholder="例：询问用户所在城市，最好精确到小区"
                  @change="saveField(selected, 'prompt')"></textarea>
      </div>
      <div class="qt-field">
        <label>后继任务（完成后自动激活为「进行中」）</label>
        <div v-for="rid in (selected.next_task_ids || [])" :key="rid" class="qt-ref-row">
          <span :title="rid">[[ rid ]]</span>
          <button @click="removeNext(selected, rid)">✕</button>
        </div>
        <div class="qt-ref-row">
          <select v-model="newNextId"><option value="">— 选后继任务 —</option>
            <option v-for="t in otherTasks" :key="t.id" :value="t.id">[[ t.id ]]</option>
          </select>
          <button class="add-btn" @click="addNext(selected)">＋</button>
        </div>
      </div>
      <div class="qt-field">
        <label>创建 / 更新时间</label>
        <div class="qt-readonly">创建 [[ fmtTs(selected.created_at) ]]</div>
        <div class="qt-readonly">更新 [[ fmtTs(selected.updated_at) ]]</div>
      </div>
      <div class="qt-field">
        <label>画布位置 pos（拖动节点自动更新）</label>
        <div class="row">
          <div><label>X</label><input type="number" v-model.number="selected.pos.x" @change="saveField(selected, 'pos')"></div>
          <div><label>Y</label><input type="number" v-model.number="selected.pos.y" @change="saveField(selected, 'pos')"></div>
        </div>
      </div>
      <div class="qt-field">
        <label>沙箱试跑（与真机同一 complete_task 逻辑）</label>
        <div class="row" style="margin-bottom:6px">
          <div><label>user</label><input type="text" v-model="simUser" placeholder="__design__"></div>
          <div><label>reason</label><input type="text" v-model="simReason" placeholder="完成原因/进展"></div>
        </div>
        <button class="btn" style="width:100%;text-align:center;padding:5px 8px;font-size:12px"
                @click="simComplete(selected)">完成并推进（complete_task）</button>
        <div v-if="simOut" class="qt-sim-out">[[ simOut ]]</div>
      </div>
      <div class="qt-btn-row">
        <button class="btn ghost" style="color:#ff6b6b;flex:none;width:100%" @click="deleteTask">删除任务</button>
      </div>
    </aside>
  </div>

  <div v-if="newModal" class="qt-modal" @click.self="newModal=false">
    <div class="qt-modal-box">
      <h3 style="margin:0;font-size:13px">新建剧本</h3>
      <input ref="newNameInput" type="text" v-model="newName" maxlength="64"
             placeholder="剧本名：小写字母 / 数字 / 下划线 / 中划线"
             @keydown.enter="confirmNew" @keydown.esc="newModal=false">
      <div class="qt-modal-actions">
        <button class="btn" @click="confirmNew">创建</button>
        <button class="btn ghost" @click="newModal=false">取消</button>
      </div>
      <div v-if="newErr" class="qt-err">[[ newErr ]]</div>
    </div>
  </div>
</div>
{% endblock %}

{% block scripts %}
<script>
const { createApp } = Vue;
const api = async (path, opts = {}) => {
  const method = opts.method || 'GET';
  // GET 带时间戳防浏览器缓存（编辑器同一 URL 有 PUT 写后回读，缓存会拿到旧 JSON）
  if (method === 'GET') path += (path.includes('?') ? '&' : '?') + '_t=' + Date.now();
  const init = { method, headers: { 'Content-Type': 'application/json' } };
  if (opts.body !== undefined) init.body = JSON.stringify(opts.body);
  const res = await fetch(path, init);
  const data = await res.json().catch(() => ({}));
  if (!data.ok) throw new Error(data.error || ('HTTP ' + res.status));
  return data;
};
const clone = (o) => JSON.parse(JSON.stringify(o));

createApp({
  delimiters: ['[[', ']]'],
  data() {
    return {
      playbooks: [], pbName: '', pb: null,
      instances: {},
      selectedId: null, selected: null, undoStack: [],
      newNextId: '', simUser: '', simReason: '', simOut: '',
      edgeColor: '#7dd3fc',
      savedOn: false, savedTimer: null,
      drag: null, linkDrag: null, pan: null,
      linkArm: null, resizeDrag: null,
      zoom: 1, panX: 0, panY: 0,
      editingField: null,
      paletteDragging: false,
      ctxMenu: null,
      newModal: false, newName: '', newErr: '',
      topErr: '',
    };
  },
  computed: {
    tasks() { return (this.pb && this.pb.tasks) || []; },
    edges() {
      const out = [];
      for (const t of this.tasks) {
        for (const rid of (t.next_task_ids || [])) out.push({ from: t.id, to: rid });
      }
      return out;
    },
    otherTasks() { return this.tasks.filter(t => t.id !== this.selectedId); },
    canvasSize() {
      let w = 1200, h = 800;
      for (const t of this.tasks) {
        w = Math.max(w, t.pos.x + this.nodeW(t) + 160);
        h = Math.max(h, t.pos.y + this.nodeH(t) + 120);
      }
      return { w, h };
    },
    worldStyle() {
      return { transform: `translate(${this.panX}px, ${this.panY}px) scale(${this.zoom})` };
    },
  },
  methods: {
    byId(id) { return this.tasks.find(t => t.id === id) || null; },
    nodeW(t) { return Math.max(t.pos.width || 210, 210); },
    nodeH(t) { return Math.max(t.pos.height || 120, 120); },
    nodeRect(t) { return { x: t.pos.x, y: t.pos.y, w: this.nodeW(t), h: this.nodeH(t) }; },
    portPos(t, port) {
      const r = this.nodeRect(t);
      if (port === 'in') return { x: r.x, y: r.y + 40 };  // 输入口在节点头部下方行
      return { x: r.x + r.w, y: r.y + 40 };               // 后继口同高、右缘
    },
    nodeStyle(t) { return { left: t.pos.x + 'px', top: t.pos.y + 'px', width: this.nodeW(t) + 'px', height: (t.pos.height || 120) + 'px' }; },
    edgePath(e) {
      const a = this.portPos(this.byId(e.from), 'out');
      const b = this.portPos(this.byId(e.to), 'in');
      if (!a || !b) return '';
      const dx = Math.max(60, Math.abs(b.x - a.x) * 0.5);
      return `M ${a.x} ${a.y} C ${a.x + dx} ${a.y}, ${b.x - dx} ${b.y}, ${b.x} ${b.y}`;
    },
    typeText(type) {
      return type === 'daily' ? '日常' : type === 'long_term' ? '长期' : '一次性';
    },
    typeHint(type) {
      return type === 'daily'
        ? '日常任务：进入进行中后永不结束，每次完成调用 complete_task 记入该用户当日记录（每用户每日一次）'
        : type === 'long_term'
        ? '长期任务：进入进行中后永不结束，每次实质进展调用 complete_task 记入该用户档案（累计）'
        : '一次性任务：完成即收尾（completed），并自动激活后继任务';
    },
    inst(t) { return t ? (this.instances[t.id] || null) : null; },
    instStatus(t) { const i = this.inst(t); return i ? i.status : 'not_started'; },
    instText(t) {
      const i = this.inst(t);
      if (!i) return '未开始';
      return i.status === 'running' ? '进行中' : i.status === 'completed' ? '已完成' : '未开始';
    },
    upstreamCount(t) {
      let n = 0;
      for (const o of this.tasks) {
        if (o !== t && (o.next_task_ids || []).includes(t.id)) n += 1;
      }
      return n;
    },
    fmtTs(iso) {
      if (!iso) return '—';
      const d = new Date(iso);
      if (isNaN(d.getTime())) return String(iso);
      return d.toLocaleString('zh-CN', { hour12: false });
    },

    flashSaved() {
      this.savedOn = true;
      clearTimeout(this.savedTimer);
      this.savedTimer = setTimeout(() => { this.savedOn = false; }, 1200);
    },

    async loadPlaybooks() {
      const d = await api('/api/quest/playbooks');
      this.playbooks = d.playbooks || [];
      if (!this.pbName || !this.playbooks.includes(this.pbName)) {
        this.pbName = this.playbooks.length ? this.playbooks[0] : '';
      }
      await this.loadPb();
    },
    openNewModal() {
      this.newName = '';
      this.newErr = '';
      this.newModal = true;
      this.$nextTick(() => { const el = this.$refs.newNameInput; if (el) el.focus(); });
    },
    async confirmNew() {
      const name = this.newName.trim();
      if (!name) { this.newErr = '请输入剧本名'; return; }
      if (!/^[a-z0-9_-]{1,64}$/.test(name)) {
        this.newErr = '剧本名只允许小写字母/数字/下划线/中划线，且不超过 64 字符';
        return;
      }
      try {
        await api('/api/quest/playbooks', { method: 'POST', body: { name } });
        this.playbooks = (await api('/api/quest/playbooks')).playbooks || [];
        this.pbName = name;
        this.newModal = false;
        await this.loadPb();
      } catch (err) { this.newErr = String(err.message || err); }
    },
    async savePb() {
      if (!this.pbName || !this.pb) return;
      try {
        await api(`/api/quest/playbooks/${encodeURIComponent(this.pbName)}/import`, {
          method: 'POST', body: this.pb,
        });
        this.flashSaved();
        this.topErr = '';
      } catch (err) { this.topErr = String(err.message || err); }
    },
    importClick() {
      const el = this.$refs.fileInput;
      if (el) el.click();
    },
    async onFileImport(e) {
      const file = e.target.files && e.target.files[0];
      e.target.value = '';
      if (!file) return;
      const name = file.name.replace(/\.json$/i, '');
      if (!/^[a-z0-9_-]{1,64}$/.test(name)) {
        this.topErr = `文件名不能作为剧本名（${name}）：只允许小写字母/数字/下划线/中划线`;
        return;
      }
      try {
        const text = await file.text();
        const data = JSON.parse(text);
        await api(`/api/quest/playbooks/${encodeURIComponent(name)}/import`, { method: 'POST', body: data });
        this.playbooks = (await api('/api/quest/playbooks')).playbooks || [];
        this.pbName = name;
        this.topErr = '';
        await this.loadPb();
      } catch (err) { this.topErr = String(err.message || err); }
    },
    async loadPb() {
      if (!this.pbName) return;
      const d = await api('/api/quest/playbooks/' + encodeURIComponent(this.pbName));
      this.pb = d.playbook;
      // 服务端已 normalize（新字段白名单 + pos 默认值）；前端只兜底缺 pos
      for (const t of this.pb.tasks || []) {
        if (!t.pos || typeof t.pos !== 'object') t.pos = { x: 120, y: 120, width: 210, height: 120 };
        if (typeof t.next_task_ids === 'undefined') t.next_task_ids = [];
      }
      this.selectedId = null;
      this.selected = null;
      this.undoStack = [];
      this.simOut = '';
      await this.loadState();
    },
    async loadState() {
      this.instances = {};
      if (!this.pbName) return;
      try {
        const d = await api(`/api/quest/playbooks/${encodeURIComponent(this.pbName)}/state`);
        this.instances = d.instances || {};
      } catch (err) { /* 空剧本也返回状态 */ }
    },
    onPbSwitch() { this.loadPb(); },
    onPaletteDragStart(e) {
      e.dataTransfer.setData('text/plain', 'new-task');
      e.dataTransfer.effectAllowed = 'copy';
      this.paletteDragging = true;
    },
    onPaletteDragEnd() { this.paletteDragging = false; },
    onCanvasDrop(e) {
      if (!this.paletteDragging) return;
      const p = this.worldPos(e);
      this.createTaskAt(p.x, p.y);
      this.paletteDragging = false;
    },
    onCanvasContext(e) {
      const p = this.worldPos(e);
      this.ctxMenu = { x: p.x, y: p.y };
    },
    onWindowClick() { this.ctxMenu = null; },
    ctxAddTask() {
      if (this.ctxMenu) this.createTaskAt(this.ctxMenu.x, this.ctxMenu.y);
      this.ctxMenu = null;
    },
    async createTaskAt(x, y) {
      if (!this.pbName) { this.topErr = '请先新建或载入剧本，再添加任务'; return; }
      this.pushUndo();
      this.topErr = '';
      let n = this.tasks.length + 1;
      let id = 'g_task' + n;
      while (this.tasks.some(t => t.id === id)) { n += 1; id = 'g_task' + n; }
      try {
        const d = await api(`/api/quest/playbooks/${encodeURIComponent(this.pbName)}/tasks`, {
          method: 'POST',
          body: { id, type: 'once', prompt: '新任务描述', pos: { x: Math.max(0, Math.round(x - 100)), y: Math.max(0, Math.round(y - 48)), width: 210, height: 120 } },
        });
        this.flashSaved();
        await this.loadPb();
        this.selectTask(this.byId(d.task.id));
      } catch (err) { this.topErr = String(err.message || err); }
    },

    isEditing(t, field) {
      return !!(this.editingField && this.editingField.t === t && this.editingField.field === field);
    },
    startEdit(t, field) {
      this.selectTask(t);
      this.editingField = { t, field, oldId: t.id, oldVal: t[field] };
      this.$nextTick(() => {
        const el = this.$el && this.$el.querySelector('.qt-edit-on');
        if (el) { el.focus(); if (el.select) el.select(); }
      });
    },
    cancelEdit(t, field) {
      if (!this.isEditing(t, field)) return;
      const { oldVal } = this.editingField;
      t[field] = oldVal;  // 恢复旧值（id 可能已被 v-model 改动）
      this.editingField = null;
    },
    async finishEdit(t, field) {
      if (!this.isEditing(t, field)) return;
      const focus = this.editingField;
      this.editingField = null;
      await this.saveField(t, field, focus);
    },
    async saveField(t, field, focus) {
      this.pushUndo();
      focus = focus || { oldId: t.id, oldVal: t[field] };
      if (field === 'id') {
        const newId = String(t.id || '').trim();
        if (!/^[a-zA-Z0-9_.\-]{1,64}$/.test(newId)) {
          t.id = focus.oldId;  // 恢复原值，不整页刷新
          this.topErr = 'id 非法（字母/数字/_.-，≤64），已恢复原值';
          return;
        }
        if (this.tasks.some(o => o !== t && o.id === newId)) {
          t.id = focus.oldId;
          this.topErr = 'id 不能重复，已恢复原值';
          return;
        }
      }
      const urlId = field === 'id' && focus ? focus.oldId : t.id;
      try {
        await api(`/api/quest/playbooks/${encodeURIComponent(this.pbName)}/tasks/${encodeURIComponent(urlId)}`, {
          method: 'PUT', body: { [field]: t[field] },
        });
        this.flashSaved();
        this.topErr = '';
        if (field === 'id') {
          // 改名成功：本地同步其他任务的后继引用（与服务端一致），沙箱实例已由服务端改名
          for (const o of this.tasks) {
            if (o === t) continue;
            const list = (o.next_task_ids || []);
            for (let k = 0; k < list.length; k += 1) {
              if (list[k] === focus.oldId) list[k] = t.id;
            }
          }
          this.selectedId = t.id;
          this.selected = t;
          await this.loadState();
        }
      } catch (err) {
        if (field === 'id') t.id = focus.oldId;  // 保存失败恢复原 id（服务端未变）
        this.topErr = String(err.message || err);
      }
    },
    async setState(t, status) {
      try {
        await api(`/api/quest/playbooks/${encodeURIComponent(this.pbName)}/simulate/${encodeURIComponent(t.id)}`, {
          method: 'POST', body: { action: 'set_state', status, result: status === 'completed' ? '手动完成' : undefined },
        });
        await this.loadState();
      } catch (err) { this.topErr = String(err.message || err); }
    },
    onTypeChange(t, e) {
      const v = e.target.value;
      if (v !== (t.type || 'once')) {
        t.type = v;
        this.saveField(t, 'type');
      }
    },
    selectTask(t) { this.selectedId = t.id; this.selected = t; },
    onNodeClick(t) {
      // 连线模式下点目标任务 → 完成连线；点回源任务 = 取消
      if (this.linkArm) {
        const from = this.linkArm;
        this.linkArm = null;
        if (from !== t.id) this.connectEdge(from, t.id);
        return;
      }
      this.selectTask(t);
    },
    onNodeDown(e, t) {
      if (e.target.closest('.qt-port') || e.target.closest('.qt-resize')) return;
      this.selectTask(t);
      const p = this.worldPos(e);
      this.drag = { id: t.id, ox: p.x - t.pos.x, oy: p.y - t.pos.y, moved: false };
    },
    onResizeDown(e, t) {
      this.selectTask(t);
      const c = this.canvasPos(e);
      this.resizeDrag = { id: t.id, startH: t.pos.height || 120, sy: c.y };
    },
    onMove(e) {
      if (this.drag) {
        const p = this.worldPos(e);
        const t = this.byId(this.drag.id);
        if (t) {
          t.pos.x = Math.max(0, Math.round(p.x - this.drag.ox));
          t.pos.y = Math.max(0, Math.round(p.y - this.drag.oy));
          this.drag.moved = true;
        }
      }
      if (this.resizeDrag) {
        const t = this.byId(this.resizeDrag.id);
        if (t) {
          const c = this.canvasPos(e);
          const delta = Math.round((c.y - this.resizeDrag.sy) / this.zoom);
          t.pos.height = Math.min(600, Math.max(90, this.resizeDrag.startH + delta));
        }
      }
      if (this.linkDrag && this.linkDrag.from) {
        const p = this.worldPos(e);
        const a = this.portPos(this.byId(this.linkDrag.from), 'out');
        this.linkDrag.x1 = a.x; this.linkDrag.y1 = a.y;
        this.linkDrag.x2 = p.x; this.linkDrag.y2 = p.y;
      }
      if (this.pan) {
        const c = this.canvasPos(e);
        this.panX = this.pan.tx0 + (c.x - this.pan.sx) / this.zoom;
        this.panY = this.pan.ty0 + (c.y - this.pan.sy) / this.zoom;
      }
    },
    async onUp(e) {
      // 1) 拉伸节点高度 → 保存
      if (this.resizeDrag && this.resizeDrag.id) {
        const rd = this.resizeDrag;
        this.resizeDrag = null;
        this.drag = null;
        this.linkDrag = null;
        this.pan = null;
        this.savePos(rd.id);
        return;
      }
      // 2) 拖节点 → 保存位置
      if (this.drag && this.drag.moved && this.drag.id) this.savePos(this.drag.id);
      // 3) 连线松手：窗口级命中判定——松开在目标任务「任意部位」都能连上
      //    （elementFromPoint 兜底节点 body/端口/头部等所有子元素，不受事件冒泡影响）；
      //    原地松开在自己后继口上 = 进入「点选连线」模式（源口脉冲提示，再点目标任务）
      const linkFrom = this.linkDrag && this.linkDrag.from;
      if (linkFrom) {
        const x = e && e.clientX != null ? e.clientX : 0;
        const y = e && e.clientY != null ? e.clientY : 0;
        const el = (x || y) ? document.elementFromPoint(x, y) : null;
        const nodeEl = el && el.closest ? el.closest('.qt-node') : null;
        const toId = nodeEl ? nodeEl.getAttribute('data-id') : null;
        this.linkDrag = null;
        this.drag = null;
        this.pan = null;
        if (toId && toId !== linkFrom) {
          await this.connectEdge(linkFrom, toId);  // 已重载画布
        } else if (nodeEl && nodeEl.getAttribute('data-id') === linkFrom) {
          // 原地点击后继口 → 进入「点选连线」模式。延迟到本节点 click 事件
          // （会先走 onNodeClick 的普通选择）之后再武装，避免被立刻当作取消消费
          const srcId = linkFrom;
          setTimeout(() => {
            this.linkArm = srcId;
            this.selectTask(this.byId(srcId));
          }, 0);
        }
        return;
      }
      this.drag = null;
      this.linkDrag = null;
      this.pan = null;
    },
    async connectEdge(fromId, toId) {
      this.pushUndo();
      try {
        await api(`/api/quest/playbooks/${encodeURIComponent(this.pbName)}/edges`, {
          method: 'PUT',
          body: { from: fromId, to: toId },
        });
        this.flashSaved();
        this.topErr = '';
        await this.loadPb();
      } catch (err) { this.topErr = String(err.message || err); }
    },
    canvasPos(e) {
      // 内容坐标（含滚动偏移）：节点 pos 存的是画布内容坐标
      const c = this.$refs.canvas;
      const r = c.getBoundingClientRect();
      return { x: e.clientX - r.left + c.scrollLeft, y: e.clientY - r.top + c.scrollTop };
    },
    worldPos(e) {
      // 世界坐标（内容坐标逆变换：减去平移、除以缩放）
      const c = this.canvasPos(e);
      return { x: c.x / this.zoom - this.panX, y: c.y / this.zoom - this.panY };
    },
    onWheel(e) {
      // 仅 ctrl/cmd+滚轮（含触控板捏合）缩放；普通滚动留给画布滚动条
      if (!(e.ctrlKey || e.metaKey)) return;
      e.preventDefault();
      const c = this.canvasPos(e);
      const k2 = Math.min(2.5, Math.max(0.3, this.zoom * (e.deltaY < 0 ? 1.1 : 1 / 1.1)));
      if (k2 === this.zoom) return;
      // 保持光标下的世界坐标不动
      const wx = c.x / this.zoom - this.panX;
      const wy = c.y / this.zoom - this.panY;
      this.zoom = k2;
      this.panX = c.x / k2 - wx;
      this.panY = c.y / k2 - wy;
    },
    zoomBy(f) {
      const c = { x: this.$refs.canvas.clientWidth / 2, y: this.$refs.canvas.clientHeight / 2 };
      const k2 = Math.min(2.5, Math.max(0.3, this.zoom * f));
      const wx = c.x / this.zoom - this.panX;
      const wy = c.y / this.zoom - this.panY;
      this.zoom = k2;
      this.panX = c.x / k2 - wx;
      this.panY = c.y / k2 - wy;
    },
    resetView() { this.zoom = 1; this.panX = 0; this.panY = 0; },
    onCanvasDown(e) {
      // 空白处左键 / 任意中键 → 平移画布；按下空白也取消「点选连线」模式
      const t = e.target;
      if (e.button === 1 || t === this.$refs.canvas || t === this.$refs.world || t === this.$refs.worldInner) {
        if (this.linkArm) this.linkArm = null;
        const c = this.canvasPos(e);
        this.pan = { sx: c.x, sy: c.y, tx0: this.panX, ty0: this.panY };
      }
    },
    async savePos(id) {
      const t = this.byId(id);
      if (!t) return;
      this.pushUndo();
      try {
        await api(`/api/quest/playbooks/${encodeURIComponent(this.pbName)}/tasks/${encodeURIComponent(id)}`, { method: 'PUT', body: { pos: t.pos } });
        this.flashSaved();
      } catch (err) { this.topErr = String(err.message || err); }
    },

    onPortDown(e, t) {
      const a = this.portPos(t, 'out');
      this.linkDrag = { from: t.id, port: 'out', x1: a.x, y1: a.y, x2: a.x, y2: a.y };
    },

    async removeEdge(e, edge) {
      e.stopPropagation();
      if (!window.confirm(`删除连线 ${edge.from} → ${edge.to}？`)) return;
      this.pushUndo();
      try {
        await api(`/api/quest/playbooks/${encodeURIComponent(this.pbName)}/edges?from=${encodeURIComponent(edge.from)}&to=${encodeURIComponent(edge.to)}`, { method: 'DELETE' });
        this.flashSaved();
        await this.loadPb();
      } catch (err) { this.topErr = String(err.message || err); }
    },

    async deleteTask() {
      if (!this.selectedId) return;
      if (!window.confirm('删除任务 ' + this.selectedId + '？其被其它任务引用的后继连线会被清除。')) return;
      this.pushUndo();
      try {
        await api(`/api/quest/playbooks/${encodeURIComponent(this.pbName)}/tasks/${encodeURIComponent(this.selectedId)}`, { method: 'DELETE' });
        this.flashSaved();
        this.selectedId = null;
        this.selected = null;
        await this.loadPb();
      } catch (err) { this.topErr = String(err.message || err); }
    },

    async addNext(t) {
      const rid = this.newNextId;
      if (!rid || !t) return;
      const list = t.next_task_ids || (t.next_task_ids = []);
      if (list.includes(rid)) { this.newNextId = ''; return; }
      list.push(rid);
      this.newNextId = '';
      await this.saveField(t, 'next_task_ids');
    },
    async removeNext(t, rid) {
      const list = t.next_task_ids || [];
      const idx = list.indexOf(rid);
      if (idx < 0) return;
      list.splice(idx, 1);
      await this.saveField(t, 'next_task_ids');
    },

    async simComplete(t) {
      this.simOut = '';
      try {
        const user = (this.simUser || '').trim() || '__design__';
        const reason = (this.simReason || '').trim();
        const d = await api(`/api/quest/playbooks/${encodeURIComponent(this.pbName)}/simulate/${encodeURIComponent(t.id)}`, {
          method: 'POST', body: { action: 'complete', user, reason },
        });
        await this.loadState();
        const r = d.result || {};
        if (r.type === 'once') {
          const act = (r.activated || []).map(x => x.task_id).join(', ');
          this.simOut = `→ 已完成 completed\n后继激活：${act || '（无）'}`;
        } else {
          this.simOut = `→ ${r.type === 'daily' ? '日常' : '长期'} 记录 ${r.deduped ? '已存在（deduped，未重复写）' : '已写入'}\n路径：${r.path || ''}`;
        }
      } catch (err) { this.topErr = String(err.message || err); }
    },

    pushUndo() {
      this.undoStack.push(JSON.stringify(this.tasks));
      if (this.undoStack.length > 50) this.undoStack.shift();
    },
    async undo() {
      const prev = this.undoStack.pop();
      if (!prev) { this.topErr = '没有可撤回的操作'; return; }
      try {
        await api(`/api/quest/playbooks/${encodeURIComponent(this.pbName)}/import`, {
          method: 'POST', body: { name: this.pbName, tasks: JSON.parse(prev) },
        });
        this.flashSaved();
        await this.loadPb();
      } catch (err) { this.topErr = String(err.message || err); }
    },
    onKeydown(e) {
      // 输入框/下拉里不拦截按键
      const tag = String(e.target && e.target.tagName || '').toLowerCase();
      if (tag === 'input' || tag === 'textarea' || tag === 'select') return;
      if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'z') {
        e.preventDefault();
        this.undo();
      } else if (e.key === 'Escape') {
        if (this.linkArm) this.linkArm = null;
      } else if (e.key === 'Delete' && this.selectedId) {
        e.preventDefault();
        this.deleteTask();
      }
    },

    exportPb() {
      window.location.href = `/api/quest/playbooks/${encodeURIComponent(this.pbName)}/export`;
    },
  },
  mounted() {
    window.addEventListener('mousemove', this.onMove);
    window.addEventListener('mouseup', this.onUp);
    window.addEventListener('click', this.onWindowClick);
    window.addEventListener('keydown', this.onKeydown);
    this.loadPlaybooks();
  },
  beforeUnmount() {
    window.removeEventListener('mousemove', this.onMove);
    window.removeEventListener('mouseup', this.onUp);
    window.removeEventListener('click', this.onWindowClick);
    window.removeEventListener('keydown', this.onKeydown);
  },
}).mount('#questApp');
</script>
{% endblock %}

settings.html:
{% extends "base.html" %}
{% block page_title %}系统配置 · OpenDesk{% endblock %}
{% block extra_head %}
  <script src="/static/vendor/vue.global.prod.min.js"></script>
{% endblock %}
{% block content %}
  <header class="page-header">
    <h1>系统配置</h1>
    <p class="page-lead">修改 <code class="mono">config.yaml</code> 中的常用项。保存后需重启 <code class="mono">deskbot-server</code> 主进程方生效。</p>
  </header>
  {% raw %}
  <div id="app">
    <div class="card">
      <h3 style="margin-top:0;">服务状态</h3>
      <p>Deskbot Server ({{ health.deskbot_target }}):
        <b :class="health.deskbot_server ? 'ok' : 'bad'">{{ health.deskbot_server ? '在线' : '离线' }}</b>
      </p>
      <p>TTS（{{ health.tts_provider || 'doubao' }}）:
        <b :class="health.tts_configured ? 'ok' : 'bad'">{{ health.tts_configured ? '已配置' : '未配置 API Key' }}</b>
      </p>
      <button @click="refreshHealth">刷新状态</button>
    </div>
    <div class="card">
      <h3 style="margin-top:0;">常用配置</h3>
      <div class="row">
        <label>Deskbot 端口</label>
        <input v-model="form.server_port" />
      </div>
      <div class="row">
        <label>ASR 语言</label>
        <input v-model="form.asr_language" placeholder="zh / auto" />
      </div>
      <div class="row">
        <label>VAD 模式</label>
        <input v-model="form.vad_mode" placeholder="0~3" />
      </div>
      <div class="row">
        <label>TTS provider</label>
        <input v-model="form.tts_provider" placeholder="doubao" />
      </div>
      <button @click="saveConfig">保存配置</button>
      <button @click="loadConfig">重载配置</button>
      <p class="muted" style="margin-top:8px;">{{ message }}</p>
    </div>
  </div>
  <style>
    #app .row { display: grid; grid-template-columns: 120px 1fr; gap: 8px; align-items: center; margin-bottom: 8px; }
    #app button { margin-right: 8px; }
  </style>
  <script>
    const { createApp } = Vue;
    createApp({
      data() {
        return {
          form: {
            server_port: 9000,
            asr_language: "zh",
            vad_mode: 1,
            tts_provider: "doubao",
          },
          health: { deskbot_server: false, tts_configured: false, tts_provider: "doubao", deskbot_target: "-" },
          message: "",
        };
      },
      methods: {
        async loadConfig() {
          const res = await fetch("/api/config");
          const cfg = await res.json();
          this.form.server_port = cfg.server?.port ?? 9000;
          this.form.asr_language = cfg.asr?.language ?? "zh";
          this.form.vad_mode = cfg.vad?.mode ?? 1;
          this.form.tts_provider = cfg.tts?.provider ?? "doubao";
          this.message = "配置已加载";
        },
        async saveConfig() {
          const res = await fetch("/api/config", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(this.form),
          });
          const result = await res.json();
          this.message = result.ok ? "保存成功（请重启 deskbot-server 生效）" : "保存失败";
        },
        async refreshHealth() {
          const res = await fetch("/api/health");
          this.health = await res.json();
        },
      },
      async mounted() {
        await this.loadConfig();
        await this.refreshHealth();
      },
    }).mount("#app");
  </script>
  {% endraw %}
{% endblock %}
